import { Track } from "./types";

export const awsTrack: Track = {
  id: "aws",
  title: "AWS",
  titleBn: "AWS",
  tagline: "Master cloud infrastructure, deployment, and DevOps",
  taglineBn: "ক্লাউড ইনফ্রাস্ট্রাকচার, ডিপ্লয়মেন্ট এবং ডেভঅপস মাস্টার",
  icon: "☁️",
  colorVar: "--aws-color",
  brandColor: "#FF9900",
  glowColor: "rgba(255,153,0,0.3)",
  totalChapters: 85,
  estimatedHours: 170,
  chapters: [  { id:"c1", title:"What Is Cloud Computing?", titleBn:"ক্লাউড কম্পিউটিং কী?", part:"Cloud Foundations", sections:[{"id":"s1","type":"lesson","title":"Cloud Computing Defined","content":"Cloud computing delivers on-demand computing resources—servers, storage, databases, networking, software—over the internet on a pay-as-you-go basis. Instead of owning physical data centers, you access technology services from a cloud provider as needed. The five essential characteristics defined by NIST are: on-demand self-service, broad network access, resource pooling, rapid elasticity, and measured service. Cloud computing enables businesses to scale globally, innovate faster, and reduce infrastructure management overhead. This model transforms capital expenditure into operational expenditure, making enterprise-grade infrastructure accessible to organizations of all sizes."},{"id":"s2","type":"lesson","title":"Cloud Service Models","content":"Cloud computing offers three primary service models. Infrastructure as a Service (IaaS) provides virtualized computing resources like servers, storage, and networking—you manage the OS, middleware, and applications while the provider manages the physical hardware. Platform as a Service (PaaS) delivers a managed platform for developing and deploying applications without worrying about underlying infrastructure—AWS Elastic Beanstalk is an example. Software as a Service (SaaS) provides fully managed software applications accessed via a browser, like Gmail or Salesforce. AWS spans all three models, giving flexibility based on how much control you want to retain."},{"id":"s3","type":"lesson","title":"Deployment Models","content":"There are three main cloud deployment models. Public cloud delivers services over the public internet and shares infrastructure across multiple customers. Private cloud is used exclusively by one organization, offering more control and isolation—often run on-premises or in a hosted data center. Hybrid cloud combines public and private, allowing data and applications to be shared between them. Many enterprises adopt a hybrid strategy to keep sensitive workloads on-premises while leveraging the public cloud for elasticity and innovation. AWS Outposts, AWS Direct Connect, and VPN solutions enable hybrid architectures."},{"id":"s4","type":"quiz","question":"Which cloud service model gives you the most control over infrastructure?","options":["SaaS","PaaS","IaaS","FaaS"],"correct":2,"explanation":"IaaS gives you control over the OS, middleware, and applications while the provider manages the physical hardware."},{"id":"s5","type":"exercise","title":"Identify Cloud Benefits","description":"List three benefits of cloud computing and explain how each helps a startup versus a large enterprise."}] },
  { id:"c2", title:"AWS Overview", titleBn:"AWS ওভারভিউ", part:"Cloud Foundations", sections:[{"id":"s1","type":"lesson","title":"What is AWS?","content":"Amazon Web Services (AWS) is the world's most comprehensive and broadly adopted cloud platform, offering over 200 fully featured services from data centers globally. Launched in 2006, AWS provides everything from compute, storage, and databases to machine learning, analytics, and IoT. Millions of customers—including the largest enterprises, fastest-growing startups, and leading government agencies—use AWS to lower costs, increase agility, and innovate faster. AWS is known for pay-as-you-go pricing, extensive global infrastructure, and commitment to security and compliance certifications."},{"id":"s2","type":"lesson","title":"AWS Service Categories","content":"AWS services are organized into categories: Compute (EC2, Lambda, ECS, EKS), Storage (S3, EBS, EFS, Glacier), Database (RDS, DynamoDB, ElastiCache, Redshift), Networking (VPC, CloudFront, Route 53, API Gateway), Security (IAM, KMS, Shield, WAF), Developer Tools (CodePipeline, CodeBuild, CloudFormation), Management (CloudWatch, CloudTrail, Trusted Advisor), Analytics (Athena, EMR, Kinesis), Machine Learning (SageMaker, Rekognition, Comprehend), and Application Integration (SQS, SNS, Step Functions)."},{"id":"s3","type":"lesson","title":"AWS Well-Architected Framework","content":"The AWS Well-Architected Framework provides best practices for designing and operating reliable, secure, efficient, cost-effective, and sustainable systems. It is organized around six pillars: Operational Excellence for running and monitoring systems, Security for protecting data and systems, Reliability for recovering from failures, Performance Efficiency for using resources efficiently, Cost Optimization for avoiding unnecessary costs, and Sustainability for minimizing environmental impact. The Well-Architected Tool helps review workloads against these pillars."},{"id":"s4","type":"quiz","question":"How many pillars does the Well-Architected Framework have?","options":["Four","Five","Six","Seven"],"correct":2,"explanation":"Six pillars: Operational Excellence, Security, Reliability, Performance Efficiency, Cost Optimization, Sustainability."},{"id":"s5","type":"exercise","title":"Explore AWS Services","description":"Choose 5 AWS service categories and list one service from each with a real-world use case."}] },
  { id:"c3", title:"AWS Global Infrastructure", titleBn:"AWS গ্লোবাল ইনফ্রাস্ট্রাকচার", part:"Cloud Foundations", sections:[{"id":"s1","type":"lesson","title":"Regions and Availability Zones","content":"AWS global infrastructure is built around Regions and Availability Zones (AZs). A Region is a geographic area with multiple, isolated locations known as Availability Zones. Each AZ is one or more discrete data centers with redundant power, networking, and connectivity, housed in separate facilities. AZs are connected through high-bandwidth, low-latency networking, making it ideal for building highly available applications. As of 2026, AWS has over 30 Regions and 100+ Availability Zones worldwide."},{"id":"s2","type":"lesson","title":"Edge Locations and Points of Presence","content":"In addition to Regions and AZs, AWS operates a global network of Edge Locations and Regional Edge Caches through Amazon CloudFront CDN. Edge Locations are used for content delivery, caching frequently accessed content closer to users for lower latency. There are over 600 Edge Locations and 40+ Regional Edge Caches worldwide. Points of Presence (PoPs) house Edge Locations and are located in major cities globally. This infrastructure supports CloudFront and AWS Global Accelerator."},{"id":"s3","type":"lesson","title":"Global vs Regional Services","content":"AWS services can be categorized as global or regional. Global services include IAM for managing users globally, Route 53 for DNS, CloudFront for CDN, and WAF for web application firewall. Regional services like EC2, S3, Lambda, and RDS operate within a specific AWS Region. When you create an EC2 instance, you select the Region and AZ. Global services span Regions while regional services need explicit cross-Region replication."},{"id":"s4","type":"quiz","question":"What connects Availability Zones within an AWS Region?","options":["Public internet","VPN tunnels","High-bandwidth low-latency networking","Satellite links"],"correct":2,"explanation":"AZs are connected through high-bandwidth, low-latency networking for highly available applications."},{"id":"s5","type":"exercise","title":"Plan Region Selection","description":"A company in Europe needs to serve users globally with GDPR compliance. Which Regions would you recommend and why?"}] },
  { id:"c4", title:"Regions and Availability Zones", titleBn:"রিজিওন এবং অ্যাভেইলেবিলিটি জোন", part:"Cloud Foundations", sections:[{"id":"s1","type":"lesson","title":"Choosing the Right Region","content":"Selecting an AWS Region requires evaluating multiple factors. Proximity to users reduces latency by deploying near your customer base. Compliance and data sovereignty may require data to stay within specific borders such as GDPR in the EU. Service availability varies across Regions. Pricing differs by Region due to different operating costs. A multi-Region strategy can optimize for latency, compliance, and cost simultaneously."},{"id":"s2","type":"lesson","title":"AZ Architecture","content":"Each AWS Region contains multiple Availability Zones (AZs), typically 3 or more. AZs are physically separated by meaningful distance to prevent correlated failures from events like fires, floods, or power outages. Each AZ has independent power, cooling, and physical security. High-bandwidth fiber connections between AZs enable synchronous replication and automatic failover. Architecting for high availability means distributing resources across multiple AZs."},{"id":"s3","type":"lesson","title":"Local Zones and Wavelength","content":"AWS Local Zones extend Regions closer to end-users for latency-sensitive applications by placing compute, storage, and database services closer to large population centers. AWS Wavelength embeds AWS compute and storage at the edge of 5G networks, enabling ultra-low latency for autonomous vehicles, live video processing, and game streaming."},{"id":"s4","type":"quiz","question":"How many AZs does a typical AWS Region have?","options":["1","2","3 or more","10+"],"correct":2,"explanation":"Most AWS Regions have 3 or more Availability Zones for high availability."},{"id":"s5","type":"exercise","title":"Design Multi-AZ Architecture","description":"Sketch a web application spanning 3 AZs. Describe what happens if one AZ fails."}] },
  { id:"c5", title:"Shared Responsibility Model", titleBn:"শেয়ার্ড রেসপনসিবিলিটি মডেল", part:"Cloud Foundations", sections:[{"id":"s1","type":"lesson","title":"Understanding Shared Responsibility","content":"Security and compliance in AWS is a shared responsibility between AWS and the customer. AWS is responsible for security OF the cloud—protecting the infrastructure that runs all AWS services including data centers, hardware, software, networking, and facilities. The customer is responsible for security IN the cloud—configuring and managing their resources correctly including customer data, IAM configurations, OS patches, network configurations, firewall rules, and client-side encryption."},{"id":"s2","type":"lesson","title":"Responsibility by Service Type","content":"For EC2 (IaaS), AWS manages the physical host, virtualization, and network. You manage the guest OS, patches, IAM, firewall rules, data encryption, and application security. For RDS (managed database), AWS handles OS, engine patches, backups, replication. You handle data access, IAM, encryption config, and security groups. For Lambda (serverless), AWS manages the runtime. You manage function code, IAM roles, env variable security, and data handling."},{"id":"s3","type":"lesson","title":"Customer Best Practices","content":"Key customer responsibilities include implementing strong IAM policies with least privilege, enabling data encryption at rest and in transit, configuring security groups and NACLs correctly, regularly patching OS and applications, using CloudTrail to monitor API activity, implementing incident response procedures, enabling AWS Config for compliance, and conducting regular security assessments."},{"id":"s4","type":"quiz","question":"Who is responsible for patching the guest OS on EC2?","options":["AWS","The customer","Shared equally","Depends on instance type"],"correct":1,"explanation":"For EC2, the customer is responsible for the guest OS including security patches."},{"id":"s5","type":"exercise","title":"Map Responsibilities","description":"Create a table comparing S3, Lambda, and DynamoDB responsibilities between AWS and the customer."}] },
  { id:"c6", title:"Cloud Pricing Basics", titleBn:"ক্লাউড প্রাইসিং বেসিক", part:"Cloud Foundations", sections:[{"id":"s1","type":"lesson","title":"AWS Pricing Philosophy","content":"AWS pricing follows four principles: Pay-as-you-go—pay for what you use without upfront commitments. Pay less when you reserve—Reserved Instances and Savings Plans offer up to 72% discount. Pay less with volume-based discounts—tiered pricing lowers per-unit cost. Pay even less as AWS grows—AWS regularly reduces prices as they achieve economies of scale."},{"id":"s2","type":"lesson","title":"Compute Pricing Models","content":"EC2 On-Demand: pay per second, no commitment, for spiky workloads. Reserved Instances: 1-3 year commitment, up to 72% discount. Spot Instances: up to 90% discount using spare capacity, 2-minute warning. Savings Plans: flexible compute commitment. Lambda: per request + per GB-second. ECS: pay for underlying resources."},{"id":"s3","type":"lesson","title":"Storage and Data Transfer Costs","content":"S3 Standard: ~$0.023/GB/month. S3 Glacier: ~$0.004/GB/month. EBS gp3: ~$0.10/GB/month. Data transfer IN to AWS is free. Data transfer OUT starts at ~$0.09/GB with tiered pricing. Data between services in same Region is often free. Cross-Region incurs charges."},{"id":"s4","type":"quiz","question":"Which pricing model offers the highest EC2 discount?","options":["On-Demand","Reserved Instances","Spot Instances","Savings Plans"],"correct":2,"explanation":"Spot Instances offer up to 90% discount but can be interrupted."},{"id":"s5","type":"exercise","title":"Estimate Monthly Costs","description":"Calculate monthly cost for: 2 t3.micro EC2, 50GB S3, 10GB data transfer out, 1M Lambda requests."}] },
  { id:"c7", title:"AWS Free Tier", titleBn:"AWS ফ্রি টায়ার", part:"Cloud Foundations", sections:[{"id":"s1","type":"lesson","title":"Understanding the Free Tier","content":"The AWS Free Tier offers Always Free services (Lambda 1M requests/month, DynamoDB 25GB, CloudWatch 10 custom metrics), 12 Months Free (750 hours t2.micro EC2, 5GB S3, 20GB EBS), and Trials (short-term for services like SageMaker). Designed for learning and experimentation at no cost. Exceeding limits incurs charges."},{"id":"s2","type":"lesson","title":"Free Tier Limits","content":"EC2: 750 hours/month t2.micro/t3.micro. S3: 5GB Standard. DynamoDB: 25GB, 25 RCU, 25 WCU. Lambda: 1M requests + 400K GB-seconds. CloudFront: 1TB transfer + 10M requests. API Gateway: 1M calls. RDS: 750 hours db.t2.micro. SES: 62K emails. SQS: 1M requests."},{"id":"s3","type":"lesson","title":"Avoiding Unexpected Charges","content":"Common causes: leaving resources running, exceeding Free Tier limits, data transfer out, unused EBS volumes, unattached Elastic IPs, NAT Gateway charges, uncovered services. Set up billing alerts immediately. Use AWS Budgets for zero-spend alerts. Tag resources with expiration dates."},{"id":"s4","type":"quiz","question":"How long does the 12-month Free Tier last?","options":["30 days","6 months","12 months","Permanent"],"correct":2,"explanation":"Valid for 12 months from AWS account creation."},{"id":"s5","type":"exercise","title":"Cost Alerts Setup","description":"Describe steps to create a billing alert for $10 threshold using AWS Budgets, SNS, and CloudWatch."}] },
  { id:"c8", title:"AWS Console Tour", titleBn:"AWS কনসোল ট্যুর", part:"Cloud Foundations", sections:[{"id":"s1","type":"lesson","title":"Navigating the Console","content":"The AWS Management Console is the web-based interface for AWS. Search bar finds services. Recent services on home page. Top navigation: Region selector, Support, account menu. AWS Health Dashboard shows service status. CloudShell provides browser-based CLI."},{"id":"s2","type":"lesson","title":"Key Features","content":"Resource Groups organize by tags. Tag Editor for bulk operations. AWS Config for compliance. Service Quotas for limits. Billing Dashboard for costs. Console Mobile App for on-the-go. CloudShell for pre-authenticated CLI."},{"id":"s3","type":"lesson","title":"Console Best Practices","content":"Use IAM users, never root. Use CloudShell for CLI. Pin frequent services. Tag resources. Review Health Dashboard. Use multi-account strategy. Follow Trusted Advisor. Use CloudWatch dashboards. Automate production with IaC."},{"id":"s4","type":"quiz","question":"Which service provides browser-based CLI?","options":["AWS CLI","AWS CloudShell","AWS Cloud9","SSM Session Manager"],"correct":1,"explanation":"CloudShell is a browser-based shell pre-authenticated with AWS CLI."},{"id":"s5","type":"exercise","title":"Explore Console","description":"List 5 services you would pin to the navigation bar and explain why each is important."}] },
  { id:"c9", title:"Cloud Security Basics", titleBn:"ক্লাউড সিকিউরিটি বেসিক", part:"Cloud Foundations", sections:[{"id":"s1","type":"lesson","title":"Cloud Security Fundamentals","content":"Cloud security encompasses policies, technologies, and controls to protect cloud-based systems, data, and infrastructure. Key principles: data encryption at rest and in transit, IAM with least privilege, network security via segmentation, compliance with regulations, monitoring and logging, incident response, and disaster recovery. AWS provides IAM, KMS, CloudTrail, GuardDuty, Security Hub, WAF, Shield, and Inspector."},{"id":"s2","type":"lesson","title":"Common Security Threats","content":"Major threats include misconfigured resources (open S3 buckets), insecure APIs, IAM privilege escalation, account hijacking, insider threats, DDoS attacks, compliance violations. AWS provides Config, Access Analyzer, GuardDuty, Shield, and Security Hub for mitigation."},{"id":"s3","type":"lesson","title":"Compliance and Certifications","content":"AWS maintains certifications across SOC, PCI DSS, ISO, HIPAA, FedRAMP, GDPR. AWS Artifact provides compliance reports. Over 90 security compliance certifications make AWS the most compliant major cloud provider."},{"id":"s4","type":"quiz","question":"Which service provides centralized security management?","options":["GuardDuty","Security Hub","Inspector","Config"],"correct":1,"explanation":"Security Hub aggregates security findings across accounts."},{"id":"s5","type":"exercise","title":"Security Checklist","description":"Create a 10-point security checklist for a new AWS account covering IAM, encryption, monitoring, and compliance."}] },
  { id:"c10", title:"AWS Architecture Principles", titleBn:"AWS আর্কিটেকচার প্রিন্সিপাল", part:"Cloud Foundations", sections:[{"id":"s1","type":"lesson","title":"Design Principles","content":"Design for failure, loosely coupled systems (SQS, SNS, API Gateway), elasticity (Auto Scaling, Lambda), parallel processing, serverless, caching (ElastiCache, CloudFront), and defense in depth security."},{"id":"s2","type":"lesson","title":"Architecting for High Availability","content":"Multi-AZ deployment, Multi-Region for critical workloads, load balancing (ELB, Route 53), Auto Scaling, health checks, stateless apps (ElastiCache, DynamoDB for sessions), database replication (RDS Multi-AZ, DynamoDB Global Tables)."},{"id":"s3","type":"lesson","title":"Architecting for Scalability","content":"Vertical scaling (bigger instance) vs horizontal scaling (more instances). Cloud-native favors horizontal for near-limitless scale. Auto Scaling Groups, read replicas, DynamoDB auto-scaling. Design stateless apps. Use caching and CDN."},{"id":"s4","type":"quiz","question":"Which scaling approach is preferred for cloud-native?","options":["Vertical","Horizontal","Diagonal","Manual"],"correct":1,"explanation":"Horizontal scaling provides near-limitless scale and better fault tolerance."},{"id":"s5","type":"exercise","title":"Design Scalable System","description":"Design a web app scaling from 100 to 1M daily users. Describe scaling strategy, services, and traffic spike handling."}] },
  { id:"c11", title:"IAM Users", titleBn:"IAM ইউজার", part:"IAM + Security", sections:[{"id":"s1","type":"lesson","title":"What is IAM?","content":"AWS Identity and Access Management (IAM) helps securely control access to AWS resources. IAM is a global service. Components: Users, Groups, Roles, Policies (JSON documents), and IAM Identity Center. Follows principle of least privilege."},{"id":"s2","type":"lesson","title":"Creating IAM Users","content":"Users represent people/services. They have a name and ARN. Access types: Programmatic (Access Key + Secret Key) and Console (password). Best practices: individual users, strong passwords, MFA, rotate keys every 90 days, remove unused users."},{"id":"s3","type":"lesson","title":"IAM User Workflows","content":"Onboarding: create user, assign to groups. Developer setup: create access keys. Contractors: time-limited permissions. Service accounts: minimum permissions. Cross-account: use roles not duplicate users. Automatic password rotation."},{"id":"s4","type":"quiz","question":"Is IAM a global or region-specific service?","options":["Region-specific","Global","AZ-specific","Account-specific"],"correct":1,"explanation":"IAM is a global service across all AWS Regions."},{"id":"s5","type":"exercise","title":"Create Users","description":"Describe steps to create 3 IAM users (admin, developer, auditor) with appropriate access."}] },
  { id:"c12", title:"IAM Groups", titleBn:"IAM গ্রুপ", part:"IAM + Security", sections:[{"id":"s1","type":"lesson","title":"Groups Overview","content":"Collections of users for shared permissions. Users can belong to up to 10 groups. Groups cannot be nested. Common: Admins, Developers, DatabaseAdmins, Auditors, Billing. Simplifies permission management."},{"id":"s2","type":"lesson","title":"Group-Based Management","content":"Attach policies to groups instead of individual users. Role changes: move user to different group. New members: add to appropriate groups. Deny always overrides Allow. Enables least privilege at scale."},{"id":"s3","type":"lesson","title":"Best Practices for Groups","content":"Meaningful naming (developers-s3-readonly). Least privilege. Managed policies preferred. Regular membership reviews. Use roles for programmatic access. Permission boundaries. IAM Identity Center for large orgs."},{"id":"s4","type":"quiz","question":"Can an IAM group contain other groups?","options":["Yes","No","Only Admin groups","Only Developer groups"],"correct":1,"explanation":"IAM groups cannot be nested—they contain only users."},{"id":"s5","type":"exercise","title":"Design Groups","description":"Design 6 IAM groups for a 50-person company across Engineering, DevOps, Finance, and HR."}] },
  { id:"c13", title:"IAM Roles", titleBn:"IAM রোল", part:"IAM + Security", sections:[{"id":"s1","type":"lesson","title":"Understanding Roles","content":"Roles are identities with permissions assumed by trusted entities (services, users, apps). Not tied to specific person. Have permission and trust policies. Common: EC2→S3, Lambda→DynamoDB, cross-account, federated users."},{"id":"s2","type":"lesson","title":"Role Types","content":"AWS service roles (EC2, Lambda). Cross-account roles. Identity provider roles (SAML, OIDC). When assumed, AWS STS provides temporary credentials (Access Key, Secret Key, Session Token) valid 15min-12hr."},{"id":"s3","type":"lesson","title":"Role vs User Guide","content":"Use users for long-term console access or service accounts. Use roles for AWS service access, cross-account, federated users, temporary credentials. Prefer roles over users—temporary credentials automatically expire."},{"id":"s4","type":"quiz","question":"Which service provides temporary credentials for roles?","options":["IAM","STS","KMS","CloudTrail"],"correct":1,"explanation":"AWS STS provides temporary credentials for IAM roles."},{"id":"s5","type":"exercise","title":"Create EC2 Role","description":"Outline steps for EC2 role to read S3 and write CloudWatch logs, attach to running instance."}] },
  { id:"c14", title:"IAM Policies", titleBn:"IAM পলিসি", part:"IAM + Security", sections:[{"id":"s1","type":"lesson","title":"Policy Structure","content":"JSON documents with Version and Statement array. Each statement: Effect (Allow/Deny), Action (e.g., s3:GetObject), Resource (ARNs), Condition (IP, MFA, time)."},{"id":"s2","type":"lesson","title":"Managed vs Inline","content":"AWS managed: pre-built, AmazonS3ReadOnlyAccess. Customer managed: created by you, reusable. Inline: embedded in single entity, not reusable. Managed recommended for most cases."},{"id":"s3","type":"lesson","title":"Policy Evaluation","content":"Default deny. Explicit allow permits. Explicit deny overrides all. Order: SCP → Resource-based → Permissions boundary → Session → Identity-based. Deny at any level overrides allows."},{"id":"s4","type":"quiz","question":"Default when no policy explicitly allows or denies?","options":["Allow","Deny","Ask confirmation","Log and allow"],"correct":1,"explanation":"All requests are denied by default unless explicitly allowed."},{"id":"s5","type":"exercise","title":"Write Policy","description":"Write JSON policy: allow list all S3 buckets, get objects from my-app-bucket, deny deletion."}] },
  { id:"c15", title:"MFA", titleBn:"MFA", part:"IAM + Security", sections:[{"id":"s1","type":"lesson","title":"What is MFA?","content":"Multi-Factor Authentication adds security beyond password with TOTP. Supports virtual MFA (Google Authenticator), hardware tokens (Gemalto, YubiKey), FIDO security keys. Root account MFA is most important security step."},{"id":"s2","type":"lesson","title":"MFA Implementation","content":"Enable on root first. Configure virtual MFA. Require via IAM policy with aws:MultiFactorAuthPresent. Enforce via SCPs. IAM Identity Center MFA. For CLI: STS GetSessionToken with MFA."},{"id":"s3","type":"lesson","title":"MFA Recovery","content":"Configure multiple MFA devices. Store backup codes securely. Enable alternative auth. Two hardware MFA for root. AWS Support can disable MFA after verification."},{"id":"s4","type":"quiz","question":"Most important account for MFA?","options":["Admin","Root","Billing","All"],"correct":1,"explanation":"Root account MFA is most critical as it has unrestricted access."},{"id":"s5","type":"exercise","title":"MFA Policy","description":"Write policy denying all API actions unless MFA authenticated in last 6 hours."}] },
  { id:"c16", title:"AWS Organizations", titleBn:"AWS অর্গানাইজেশন", part:"IAM + Security", sections:[{"id":"s1","type":"lesson","title":"Organizations Overview","content":"Centrally manage multiple AWS accounts. Create accounts, organize into OUs, apply SCPs/tag policies/backup policies. Consolidated billing for volume discounts. Management account, member accounts, OUs."},{"id":"s2","type":"lesson","title":"Multi-Account Strategy","content":"Management account for billing. Security OU for audit/logging. Infrastructure OU for networking. Workload OUs for dev/test/prod. Benefits: isolation, separate billing, easier compliance. AWS Control Tower for landing zone."},{"id":"s3","type":"lesson","title":"Service Control Policies","content":"SCPs define maximum permissions for accounts. Apply to root, OUs, accounts. Cannot affect management account. Evaluated before IAM. Common: restrict Regions, deny disabling CloudTrail, require MFA, restrict instance types."},{"id":"s4","type":"quiz","question":"Can SCPs affect the management account?","options":["Yes","No","With explicit config","Only for root"],"correct":1,"explanation":"SCPs cannot affect the management account in AWS Organizations."},{"id":"s5","type":"exercise","title":"Design Organization","description":"Design OU hierarchy for 4 teams (Dev, Test, Prod, Security) with SCP examples."}] },
  { id:"c17", title:"SCP Policies", titleBn:"SCP পলিসি", part:"IAM + Security", sections:[{"id":"s1","type":"lesson","title":"SCPs Deep Dive","content":"Restrict maximum permissions for member accounts. Define perimeter for IAM. Syntax: Effect, Action, Resource. Attach to root/OUs/accounts. Effect inherited. Support conditions, resource-level, tag-based controls."},{"id":"s2","type":"lesson","title":"Common SCP Patterns","content":"Region restriction. Service restriction. Instance type restriction. Encryption enforcement. S3 block public access. MFA requirement. Tag enforcement. Cost control."},{"id":"s3","type":"lesson","title":"SCP Strategy","content":"Start with deny-only SCPs. Test on test OU. Use CloudTrail to review denied actions. Document SCPs. Review regularly. Careful testing essential before production."},{"id":"s4","type":"quiz","question":"What if SCP denies but IAM allows?","options":["Allowed","Denied","Logged","Depends"],"correct":1,"explanation":"SCP denies override IAM allows."},{"id":"s5","type":"exercise","title":"Write SCPs","description":"Write SCPs to restrict EC2 to t3/m5 families and prevent disabling CloudTrail."}] },
  { id:"c18", title:"Secrets Manager", titleBn:"সিক্রেটস ম্যানেজার", part:"IAM + Security", sections:[{"id":"s1","type":"lesson","title":"Secrets Manager Overview","content":"Manage, retrieve, and rotate database credentials, API keys. Automatic rotation for RDS/Redshift/DocumentDB. IAM access control. KMS encryption. Cross-account/Region. $0.40/secret/month + $0.05/10K API calls."},{"id":"s2","type":"lesson","title":"Secret Rotation","content":"Lambda-based rotation. Create new secret, test, update database, deprecate old. getSecretValue API. Version stages: AWSCURRENT, AWSPREVIOUS. Implement retry logic."},{"id":"s3","type":"lesson","title":"Best Practices","content":"Never store secrets in code. Least privilege IAM. Enable automatic rotation. KMS customer keys. Monitor with CloudTrail. Tag secrets. Replicate cross-Region. Test rotation."},{"id":"s4","type":"quiz","question":"Which service encrypts Secrets Manager data?","options":["IAM","KMS","CloudHSM","ACM"],"correct":1,"explanation":"Secrets Manager uses KMS for encryption at rest."},{"id":"s5","type":"exercise","title":"Secrets Strategy","description":"Design secrets management for 3-tier app with RDS, API keys, OAuth tokens."}] },
  { id:"c19", title:"KMS Encryption", titleBn:"KMS এনক্রিপশন", part:"IAM + Security", sections:[{"id":"s1","type":"lesson","title":"KMS Overview","content":"Create and control encryption keys. Integrated with S3, EBS, RDS, DynamoDB, Lambda. HSMs protect keys. $1/month per customer managed key + $0.03/10K crypto ops. AWS managed keys are free."},{"id":"s2","type":"lesson","title":"Key Types","content":"AWS managed (free, automatic). Customer managed ($1/month, configurable rotation). Custom key stores (CloudHSM). Imported key material (BYOK). Multi-Region keys. Envelope encryption hierarchy."},{"id":"s3","type":"lesson","title":"Envelope Encryption","content":"KMS generates data key (plaintext + ciphertext). Encrypt data with plaintext key. Store encrypted key alongside. Decrypt by sending encrypted key to KMS. Prevents large data through KMS."},{"id":"s4","type":"quiz","question":"Which technique uses local key protected by KMS?","options":["Server-side","Client-side","Envelope","Field-level"],"correct":2,"explanation":"Envelope encryption encrypts data with local key then protects key with KMS."},{"id":"s5","type":"exercise","title":"Encryption Strategy","description":"Design encryption for user data in S3, RDS, DynamoDB. Specify KMS key types and envelope encryption."}] },
  { id:"c20", title:"Security Best Practices", titleBn:"সিকিউরিটি বেস্ট প্র্যাকটিস", part:"IAM + Security", sections:[{"id":"s1","type":"lesson","title":"Security Overview","content":"Identity: IAM roles, MFA, least privilege, IAM Identity Center. Detection: CloudTrail, GuardDuty, Security Hub, Config. Infrastructure: SGs, NACLs, WAF, Shield, VPC with private subnets. Data: encrypt at rest/transit."},{"id":"s2","type":"lesson","title":"S3 Security","content":"Block public access by default. Bucket policies. Server access logging. Object Lock. Default encryption. Versioning. Replication. Least privilege. Access Analyzer."},{"id":"s3","type":"lesson","title":"EC2 and VPC Security","content":"SGs as firewall. NACLs for subnet. Trusted AMIs. Regular patching. VPC Flow Logs. Session Manager. IMDSv2. EBS encryption. Dedicated instances for sensitive workloads."},{"id":"s4","type":"quiz","question":"Which service provides automated threat detection?","options":["Security Hub","GuardDuty","Inspector","Config"],"correct":1,"explanation":"GuardDuty monitors for malicious activity using ML."},{"id":"s5","type":"exercise","title":"Audit Checklist","description":"Create 20-point security audit covering IAM, S3, EC2, VPC, monitoring, encryption."}] },
  { id:"c21", title:"EC2 Basics", titleBn:"EC2 বেসিক", part:"Compute Services", sections:[{"id":"s1","type":"lesson","title":"EC2 Overview","content":"Amazon EC2 provides scalable virtual servers. Components: AMI (OS template), Instance Type (CPU/RAM), EBS (storage), Security Groups (firewall), Key Pairs (SSH), User Data (bootstrapping)."},{"id":"s2","type":"lesson","title":"Instance Lifecycle","content":"Pending (starting), Running (active, billing), Stopped (no compute, EBS persists), Terminated (deleted). Hibernate saves RAM to EBS. Termination protection."},{"id":"s3","type":"lesson","title":"Instance Types","content":"Family.Generation.Size (t3.large). General Purpose (T3, M6g), Compute Optimized (C6g), Memory Optimized (R6g, X2g), Storage Optimized (I3), Accelerated (P4, G5)."},{"id":"s4","type":"quiz","question":"What determines EC2 OS?","options":["Instance type","AMI","Security group","Key pair"],"correct":1,"explanation":"The AMI determines the operating system."},{"id":"s5","type":"exercise","title":"Launch Instance","description":"Describe steps: t3.micro, Amazon Linux 2, 20GB gp3, SSH-only security group."}] },
  { id:"c22", title:"EC2 Pricing Models", titleBn:"EC2 প্রাইসিং মডেল", part:"Compute Services", sections:[{"id":"s1","type":"lesson","title":"On-Demand","content":"Pay per second, no commitment. Ideal for spiky workloads, dev/test. Most flexible but most expensive. t3.micro ~$0.0104/hour."},{"id":"s2","type":"lesson","title":"Reserved Instances","content":"1-3 year commitment. Standard up to 72%. Convertible up to 54%. Savings Plans: commit to $/hour. Compute Savings Plans apply to EC2, Lambda, Fargate."},{"id":"s3","type":"lesson","title":"Spot Instances","content":"Up to 90% discount. 2-minute warning. For batch, CI/CD, stateless apps. Spot Fleet combines Spot + On-Demand. Dedicated Hosts for existing licenses."},{"id":"s4","type":"quiz","question":"Highest discount model?","options":["On-Demand","Reserved","Spot","Dedicated"],"correct":2,"explanation":"Spot offers up to 90% discount."},{"id":"s5","type":"exercise","title":"Optimize Costs","description":"50 instances web app + 50 nightly batch. Recommend pricing models for each."}] },
  { id:"c23", title:"Launch Templates", titleBn:"লঞ্চ টেমপ্লেট", part:"Compute Services", sections:[{"id":"s1","type":"lesson","title":"Templates Overview","content":"Define EC2 config: AMI, type, key pair, SGs, storage, user data, IAM role, networking. Versionable. Used by ASGs, Spot Fleet. Benefits: standardization, versioning."},{"id":"s2","type":"lesson","title":"Creating Templates","content":"Specify name, AMI, type, SGs, EBS, IAM profile, networking, user data. Best: latest AMI, Parameter Store config, version per environment."},{"id":"s3","type":"lesson","title":"Templates with ASGs","content":"ASGs use templates for new instances. Simplified updates. Blue/green via new version. Lifecycle hooks. Mixed instances (On-Demand + Spot)."},{"id":"s4","type":"quiz","question":"What replaces Launch Configurations?","options":["CloudFormation","Launch Templates","EC2 Fleet","Instance Profiles"],"correct":1,"explanation":"Launch Templates supersede Launch Configurations."},{"id":"s5","type":"exercise","title":"Create Template","description":"Design template: Amazon Linux 2, t3.medium, 30GB gp3, Apache install via user data."}] },
  { id:"c24", title:"Auto Scaling Groups", titleBn:"অটো স্কেলিং গ্রুপ", part:"Compute Services", sections:[{"id":"s1","type":"lesson","title":"ASG Fundamentals","content":"Manage EC2 instances as a group. Settings: min, desired, max capacity. Work with ALB. Spread across AZs. Use Launch Templates."},{"id":"s2","type":"lesson","title":"Scaling Policies","content":"Simple (alarm + cooldown). Step (different amounts per severity). Target tracking (maintain metric like 50% CPU). Predictive (ML-based). Scheduled (time-based)."},{"id":"s3","type":"lesson","title":"Lifecycle Hooks","content":"Custom actions at launch/terminate. pending:wait / terminating:wait. Instance Refresh for rolling updates with new template version."},{"id":"s4","type":"quiz","question":"Which policy maintains target CPU?","options":["Simple","Step","Target tracking","Scheduled"],"correct":2,"explanation":"Target tracking maintains a specified metric value."},{"id":"s5","type":"exercise","title":"Design ASG","description":"Min 2, scale up at 60% CPU, down at 30% CPU, 3 AZs, ALB."}] },
  { id:"c25", title:"Elastic Load Balancers", titleBn:"ইলাস্টিক লোড ব্যালেন্সার", part:"Compute Services", sections:[{"id":"s1","type":"lesson","title":"ELB Overview","content":"Distributes traffic across targets. ALB (Layer 7, HTTP/HTTPS, path/host routing). NLB (Layer 4, TCP/UDP, ultra-low latency). GWLB (Layer 3, virtual appliances)."},{"id":"s2","type":"lesson","title":"ALB Deep Dive","content":"Path-based routing (/api vs /web). Host-based routing. Query string routing. HTTP/2, WebSocket, gRPC. Sticky sessions. TLS termination. Cognito/OIDC auth. Access logs."},{"id":"s3","type":"lesson","title":"NLB Features","content":"Layer 4, millions RPS. Preserves client IP. Static IP support. Cross-zone. Best for TCP/UDP, static IP, PrivateLink."},{"id":"s4","type":"quiz","question":"Which LB operates at Layer 7?","options":["CLB","NLB","ALB","GWLB"],"correct":2,"explanation":"ALB operates at Layer 7 with HTTP/HTTPS routing."},{"id":"s5","type":"exercise","title":"Choose LB","description":"Route api.example.com (REST) and app.example.com (WebSocket) to different groups. Which LB?"},{"id":"s4","type":"lesson","title":"Target Groups","content":"Groups of targets. Health checks (protocol, port, path, interval). Deregistration delay. Slow start. Stickiness. EC2, Lambda, IP as targets."}] },
  { id:"c26", title:"AMIs", titleBn:"AMI", part:"Compute Services", sections:[{"id":"s1","type":"lesson","title":"AMI Overview","content":"Template with OS + software config. Region-specific, copyable. Components: root volume, launch permissions, block device mapping. Sources: AWS, Marketplace, Community, Custom."},{"id":"s2","type":"lesson","title":"Creating Custom AMIs","content":"Launch, configure, stop, create AMI (EBS snapshots). Lifecycle: create, register, share, copy, deregister. Image Builder for automation."},{"id":"s3","type":"lesson","title":"EC2 Image Builder","content":"Automated pipeline: source ➔ build ➔ test ➔ distribute. Automated patching, CIS compliance, versioning, cross-Region. Pay only for build resources."},{"id":"s4","type":"quiz","question":"Are AMIs region-specific?","options":["Region-specific","Global","Account-specific","Zone-specific"],"correct":0,"explanation":"AMIs are region-specific but copyable."},{"id":"s5","type":"exercise","title":"AMI Pipeline","description":"Design weekly pipeline: hardened Amazon Linux 2, Apache, Node.js, CIS tests, us-east-1 + eu-west-1."}] },
  { id:"c27", title:"EBS Volumes", titleBn:"EBS ভলিউম", part:"Compute Services", sections:[{"id":"s1","type":"lesson","title":"EBS Overview","content":"Persistent block storage. AZ-replicated. gp3: 3000 IOPS baseline, 16K max, best price-performance. io2: 256K IOPS for databases. st1: HDD throughput. sc1: cold HDD."},{"id":"s2","type":"lesson","title":"Snapshots","content":"Incremental backups in S3. Create volumes in any AZ, migrate Regions, DR, create AMIs. Fast Snapshot Restore. Snapshot Archive (75% cost reduction). Recycle Bin."},{"id":"s3","type":"lesson","title":"Encryption","content":"KMS encryption for volumes and snapshots. Data in transit encrypted. Enable by default. Multi-Attach: up to 16 Nitro instances sharing io1/io2."},{"id":"s4","type":"quiz","question":"Best price-performance EBS?","options":["gp2","gp3","io1","st1"],"correct":1,"explanation":"gp3 offers baseline 3000 IOPS with independent scaling."},{"id":"s5","type":"exercise","title":"EBS Strategy","description":"Design 500GB, 15K IOPS, 250 MB/s, encrypted, daily snapshots retained 30 days."}] },
  { id:"c28", title:"Lambda Basics", titleBn:"ল্যাম্বডা বেসিক", part:"Compute Services", sections:[{"id":"s1","type":"lesson","title":"Lambda Overview","content":"Serverless compute, run code in response to events. Supports Node.js, Python, Java, Go, .NET, Ruby. Triggers from 200+ services. Pricing: $0.20/1M requests + per GB-second."},{"id":"s2","type":"lesson","title":"Function Configuration","content":"Memory 128MB-10GB (CPU proportional). Ephemeral storage 512MB-10GB. Execution role, VPC config, env vars (KMS), timeout up to 15 min, DLQ, provisioned concurrency, layers."},{"id":"s3","type":"lesson","title":"Execution Environment","content":"Init (download code, start runtime), Invoke (run handler), Shutdown (terminate after inactivity). Environments reused. Initialize clients outside handler. Keep stateless. Idempotency."},{"id":"s4","type":"quiz","question":"Max Lambda timeout?","options":["5 min","10 min","15 min","30 min"],"correct":2,"explanation":"Maximum execution timeout is 15 minutes."},{"id":"s5","type":"exercise","title":"Create Lambda","description":"Python function: S3 trigger, read image metadata, store in DynamoDB, log to CloudWatch."}] },
  { id:"c29", title:"Lambda Advanced", titleBn:"ল্যাম্বডা অ্যাডভান্সড", part:"Compute Services", sections:[{"id":"s1","type":"lesson","title":"Versions and Aliases","content":"Immutable version snapshots. $LATEST is current. Aliases point to versions (PROD→v3). Weighted aliases for canary (90/10). Blue/green deployments."},{"id":"s2","type":"lesson","title":"Performance Tuning","content":"Memory affects CPU proportionally. Provisioned Concurrency for zero cold starts. Reserved concurrency prevents throttling. Minimize packages. SnapStart for Java."},{"id":"s3","type":"lesson","title":"VPC and Security","content":"VPC config adds ENI latency. VPC endpoints for S3/DynamoDB. Least privilege IAM. Encrypted env vars. Lambda@Edge at CloudFront edges."},{"id":"s4","type":"quiz","question":"Which feature eliminates cold starts?","options":["Reserved concurrency","Provisioned concurrency","SnapStart","DLQ"],"correct":1,"explanation":"Provisioned Concurrency keeps pre-warmed environments."},{"id":"s5","type":"exercise","title":"Optimize Lambda","description":"300ms cold start latency. Optimize with memory, provisioned concurrency, package optimization."}] },
  { id:"c30", title:"ECS and Containers", titleBn:"ECS এবং কন্টেইনার", part:"Compute Services", sections:[{"id":"s1","type":"lesson","title":"ECS Overview","content":"Container orchestration. Fargate (serverless, pay per task) vs EC2 (manage instances). Task definitions (JSON). Clusters, services, auto scaling."},{"id":"s2","type":"lesson","title":"Fargate vs EC2","content":"Fargate: 0.25-16 vCPU, 0.5-120GB, billed per task/second. EC2: manage instances, GPU support, reserved capacity. Both used based on workload needs."},{"id":"s3","type":"lesson","title":"Task Definitions","content":"JSON: task family, IAM role, network mode (awsvpc), containers (image, ports, env, logging, health check, volumes). Immutable versions. Blue/green deployments."},{"id":"s4","type":"quiz","question":"Serverless ECS launch type?","options":["EC2","Fargate","ECS Anywhere","External"],"correct":1,"explanation":"Fargate is serverless without EC2 management."},{"id":"s5","type":"exercise","title":"Deploy Containers","description":"Design ECS for Node.js microservice with ALB, CPU scaling, CodePipeline. Fargate or EC2?"}] },
  { id:"c31", title:"S3 Basics", titleBn:"S3 বেসিক", part:"Storage + Databases", sections:[{"id":"s1","type":"lesson","title":"S3 Overview","content":"Object storage, 11 nines durability. Objects 0B-5TB in buckets. Classes: Standard, Intelligent-Tiering, Standard-IA, Glacier (Instant/Flexible/Deep Archive)."},{"id":"s2","type":"lesson","title":"Buckets and Objects","content":"Globally unique names (3-63 chars, lowercase). URL: https://bucket.s3.region.amazonaws.com/key. Multipart upload, Transfer Acceleration, Batch Operations, Object Lambda."},{"id":"s3","type":"lesson","title":"Versioning and Replication","content":"Versioning preserves all versions. Replication: SRR (same-Region), CRR (cross-Region). Filter by prefix/tags. Object Lock for WORM. Legal holds."},{"id":"s4","type":"quiz","question":"S3 Standard durability?","options":["99.99%","99.9999%","99.9999999%","99.999999999%"],"correct":3,"explanation":"S3 provides 11 nines (99.999999999%) durability."},{"id":"s5","type":"exercise","title":"Storage Strategy","description":"Media company: frequent images, rare reports, 7-year archival. Specify classes and lifecycle."}] },
  { id:"c32", title:"S3 Security", titleBn:"S3 সিকিউরিটি", part:"Storage + Databases", sections:[{"id":"s1","type":"lesson","title":"Access Control","content":"IAM policies, Bucket policies, pre-signed URLs, Access Points. All private by default with Block Public Access. Access Analyzer identifies external sharing."},{"id":"s2","type":"lesson","title":"Encryption Options","content":"SSE-S3 (AES-256). SSE-KMS (KMS keys, audit, separate permissions). SSE-C (your keys, S3 encrypts). Client-side. Default encryption. Bucket Keys reduce KMS costs 99%."},{"id":"s3","type":"lesson","title":"Access Logs","content":"Server Access Logs to S3. CloudTrail records API calls. S3 Inventory for object reports. Config rules monitor compliance. Event Notifications."},{"id":"s4","type":"quiz","question":"Which uses customer-provided keys?","options":["SSE-S3","SSE-KMS","SSE-C","Client-Side"],"correct":2,"explanation":"SSE-C: customer provides keys, S3 encrypts/decrypts."},{"id":"s5","type":"exercise","title":"Secure S3 Bucket","description":"Remediate public S3 bucket with PII: block public, encrypt, version, log."}] },
  { id:"c33", title:"S3 Lifecycle Rules", titleBn:"S3 লাইফসাইকেল রুলস", part:"Storage + Databases", sections:[{"id":"s1","type":"lesson","title":"Lifecycle Policies","content":"Transition: Standard→IA→Glacier→Deep Archive. Expiration: delete after time. Also expire incomplete multipart uploads and delete markers."},{"id":"s2","type":"lesson","title":"Design Patterns","content":"Data tiering: Standard 30d→IA 31-90→Glacier 91-365→Deep Archive 1yr+. Log rotation: IA after 7d, delete 1yr. Versioning lifecycle for noncurrent versions."},{"id":"s3","type":"lesson","title":"Costs","content":"Transition fees for API + per-GB. Minimum storage duration (IA 30d). Objects <128KB not eligible. Rules take effect next day. Monitor with CloudWatch."},{"id":"s4","type":"quiz","question":"Minimum size for IA transition?","options":["64KB","128KB","256KB","No minimum"],"correct":1,"explanation":"Objects <128KB not eligible for IA/Glacier."},{"id":"s5","type":"exercise","title":"Lifecycle Design","description":"Video app: Standard 7d→IA 30d→Glacier 1yr→delete. Include upload cleanup."}] },
  { id:"c34", title:"Glacier", titleBn:"গ্লেসিয়ার", part:"Storage + Databases", sections:[{"id":"s1","type":"lesson","title":"Glacier Overview","content":"Low-cost archival. Instant Retrieval (ms). Flexible Retrieval (1-5min expedited, 3-5hr standard, 5-12hr bulk). Deep Archive (12hr standard, ~$1/TB/month). 11 nines."},{"id":"s2","type":"lesson","title":"Vaults and Archives","content":"Archives up to 40TB in vaults. Vault Lock for WORM. Glacier Select for SQL queries. Glacier storage class via S3 Lifecycle is modern approach."},{"id":"s3","type":"lesson","title":"Best Practices","content":"Regulatory archives, medical/financial records. Plan retrieval carefully. Expedited for emergencies. Vault Lock for compliance. CloudWatch monitoring."},{"id":"s4","type":"quiz","question":"Deep Archive standard retrieval time?","options":["Instant","1-5 min","3-5 hr","12 hr"],"correct":3,"explanation":"Deep Archive has 12-hour standard retrieval."},{"id":"s5","type":"exercise","title":"Archival Strategy","description":"Healthcare: 10-year patient record retention with HIPAA. Lifecycle + Glacier strategy."}] },
  { id:"c35", title:"EFS", titleBn:"EFS", part:"Storage + Databases", sections:[{"id":"s1","type":"lesson","title":"EFS Overview","content":"Managed NFS for Linux. Auto-scales. Mount across multi-AZ. 99.99% availability. $0.08/GB/month Standard, $0.008/GB IA."},{"id":"s2","type":"lesson","title":"Performance","content":"General Purpose (low latency) or Max I/O (high throughput). Bursting (scales with storage) or Provisioned throughput. Lifecycle auto-moves between classes."},{"id":"s3","type":"lesson","title":"Security","content":"VPC security groups + IAM + POSIX. Access Points enforce user/group/root directory. Encryption at rest (KMS) + in transit (TLS)."},{"id":"s4","type":"quiz","question":"EFS mode for big data?","options":["General Purpose","Max I/O","Provisioned","Bursting"],"correct":1,"explanation":"Max I/O for high throughput parallel workloads."},{"id":"s5","type":"exercise","title":"EFS Design","description":"Web app 10 EC2 in 3 AZs. Shared file storage. Performance mode, class, security, lifecycle."}] },
  { id:"c36", title:"RDS Basics", titleBn:"RDS বেসিক", part:"Storage + Databases", sections:[{"id":"s1","type":"lesson","title":"RDS Overview","content":"Managed relational databases. Engines: Aurora (5x MySQL, 3x PostgreSQL), MySQL, MariaDB, PostgreSQL, Oracle, SQL Server. Multi-AZ, Read Replicas, auto backups, storage auto-scaling."},{"id":"s2","type":"lesson","title":"Multi-AZ HA","content":"Synchronous standby in other AZ. Auto failover 60-120s. DNS flip to standby. For DR, not read scaling."},{"id":"s3","type":"lesson","title":"Backup and Restore","content":"Daily snapshot + 5-min transaction logs. Retention 1-35 days. Manual snapshots retained indefinitely. Point-in-time restore."},{"id":"s4","type":"quiz","question":"Multi-AZ failover mechanism?","options":["DNS flip","LB redirect","Client retry","SDK handles"],"correct":0,"explanation":"RDS flips DNS from primary to standby."},{"id":"s5","type":"exercise","title":"RDS Configuration","description":"E-commerce PostgreSQL: Multi-AZ, 500GB auto-scaling, 35-day backups, read replicas."}] },
  { id:"c37", title:"RDS Scaling", titleBn:"RDS স্কেলিং", part:"Storage + Databases", sections:[{"id":"s1","type":"lesson","title":"Read Replicas","content":"Up to 15 replicas. Asynchronous. Same/cross-Region. For reporting, read-heavy apps, DR. Aurora: 15 replicas with ~10ms lag."},{"id":"s2","type":"lesson","title":"Scaling Options","content":"Vertical: change instance class. Storage: independent scaling without downtime. Auto Scaling. Provisioned IOPS. Performance Insights."},{"id":"s3","type":"lesson","title":"Amazon Aurora","content":"5x MySQL, 3x PostgreSQL. 6 copies across 3 AZs. Auto-scaling 10GB-128TB. Serverless v2. Global Database (1s lag). Multi-Master. Backtrack."},{"id":"s4","type":"quiz","question":"How many data copies in Aurora?","options":["2","3","6","9"],"correct":2,"explanation":"Aurora maintains 6 copies across 3 AZs."},{"id":"s5","type":"exercise","title":"Scale Database","description":"db.r5.large with growing reads. Design scaling with replicas, potential Aurora migration."}] },
  { id:"c38", title:"DynamoDB Basics", titleBn:"ডায়নামোডিবি বেসিক", part:"Storage + Databases", sections:[{"id":"s1","type":"lesson","title":"DynamoDB Overview","content":"NoSQL key-value/document. Single-digit ms at any scale. Serverless. Tables, items (400KB max), attributes, keys, LSI/GSI, Streams."},{"id":"s2","type":"lesson","title":"Capacity Modes","content":"On-Demand (pay per request, auto-scale). Provisioned (set RCU/WCU). RCU: 1 strongly consistent read/sec per 4KB. WCU: 1 write/sec per 1KB."},{"id":"s3","type":"lesson","title":"Primary Keys","content":"Simple (partition key only). Composite (partition + sort key). Sort key enables range queries. High cardinality partition keys. Sort keys model relationships."},{"id":"s4","type":"quiz","question":"Max DynamoDB item size?","options":["64KB","128KB","400KB","1MB"],"correct":2,"explanation":"Maximum item size is 400KB including attribute names and values."},{"id":"s5","type":"exercise","title":"DynamoDB Design","description":"Gaming leaderboard: primary key, score index, team GSI, daily/weekly queries."}] },
  { id:"c39", title:"DynamoDB Indexes", titleBn:"DynamoDB ইন্ডেক্স", part:"Storage + Databases", sections:[{"id":"s1","type":"lesson","title":"LSI","content":"Alternative sort key for same partition key. Created at table creation. Different sort key for queries. Max 5. Uses base table WCU."},{"id":"s2","type":"lesson","title":"GSI","content":"Different partition/sort key. Create anytime. Own throughput. Eventually consistent. Async replication. Up to 20. Hot partitions affect base table."},{"id":"s3","type":"lesson","title":"Index Strategy","content":"List query patterns, determine keys. Sparse indexes (GSI on optional attribute). Index overloading. Single-table design."},{"id":"s4","type":"quiz","question":"Can you add LSI after table creation?","options":["Yes","No","Within 24hr","Only empty"],"correct":1,"explanation":"LSIs must be created at table creation."},{"id":"s5","type":"exercise","title":"Index Design","description":"Social media posts (UserID+PostTimestamp). GSIs for: follower feed, tag search, trending by likes."}] },
  { id:"c40", title:"ElastiCache", titleBn:"এলাস্টিক্যাশ", part:"Storage + Databases", sections:[{"id":"s1","type":"lesson","title":"ElastiCache Overview","content":"In-memory caching. Redis or Memcached. Sub-ms latency. Redis: up to 500 nodes/250 shards, Streams, sorted sets, GeoSpatial, Lua scripting."},{"id":"s2","type":"lesson","title":"Caching Strategies","content":"Lazy loading (cache-aside). Write-through. TTL. Write-behind. Best for read-heavy, sessions, rate limiting, leaderboards."},{"id":"s3","type":"lesson","title":"Redis Use Cases","content":"Session stores, leaderboards (sorted sets), rate limiting (INCR+TTL), message queues, geospatial, analytics (HyperLogLog)."},{"id":"s4","type":"quiz","question":"Which engine supports sorted sets?","options":["Memcached","Redis","Both","Neither"],"correct":1,"explanation":"Redis supports sorted sets for leaderboards."},{"id":"s5","type":"exercise","title":"Caching Design","description":"News site 100K articles, 10M views/day. Cache key structure, TTL, invalidation with Redis."}] },
  { id:"c41", title:"VPC Basics", titleBn:"VPC বেসিক", part:"Networking", sections:[{"id":"s1","type":"lesson","title":"VPC Overview","content":"Isolated section of AWS. Components: CIDR, subnets (per AZ), route tables, IGW, NAT Gateway, VPC Peering, SGs, NACLs. 5 VPCs/Region, 200 subnets/VPC."},{"id":"s2","type":"lesson","title":"CIDR and Subnet Design","content":"/16 (65K IPs) to /28 (16 IPs). Subnets in single AZ. Public (IGW route) vs Private (no IGW). Best: /16 VPC, /24 subnets, 3 AZs."},{"id":"s3","type":"lesson","title":"Default vs Custom VPC","content":"Default: /20, subnet per AZ, IGW, ready to use. Custom: full control, multi-tier, no default public IPs, flow logs. Always create custom for production."},{"id":"s4","type":"quiz","question":"Largest VPC CIDR?","options":["/8","/16","/24","/28"],"correct":1,"explanation":"Largest CIDR is /16 (65,536 IPs)."},{"id":"s5","type":"exercise","title":"Design VPC","description":"3-tier web app: 10.0.0.0/16, public web, private app, private data across 3 AZs."}] },
  { id:"c42", title:"Subnets", titleBn:"সাবনেট", part:"Networking", sections:[{"id":"s1","type":"lesson","title":"Subnet Types","content":"Public (IGW route, public IPs). Private (no IGW). VPN-only. Minimum /28 (11 usable, 5 reserved). One per AZ. Each has route table + NACL."},{"id":"s2","type":"lesson","title":"Public Subnet Config","content":"Route 0.0.0.0/0→IGW. Auto-assign public IP. ALB, NAT Gateway, bastion hosts. Use Elastic IPs for stable addressing."},{"id":"s3","type":"lesson","title":"Private Subnet Config","content":"No IGW route. Outbound via NAT Gateway. Host EC2, RDS, Lambda, ElastiCache. Critical security boundary."},{"id":"s4","type":"quiz","question":"IPs reserved per subnet?","options":["2","3","5","10"],"correct":2,"explanation":"AWS reserves 5 IPs per subnet."},{"id":"s5","type":"exercise","title":"Subnet Strategy","description":"10.0.0.0/16 with 3 AZs. Public (ALB), private app (EC2), private data (RDS). CIDR blocks."}] },
  { id:"c43", title:"Route Tables", titleBn:"রুট টেবিল", part:"Networking", sections:[{"id":"s1","type":"lesson","title":"Route Tables Overview","content":"Routes + targets. Each subnet has one route table. Main table for unattached subnets. Local route for VPC CIDR auto-added."},{"id":"s2","type":"lesson","title":"Config Patterns","content":"Public: local + 0.0.0.0/0→IGW. Private with NAT: local + 0.0.0.0/0→NAT. VPN: on-prem CIDR→VPN. Peering: peered CIDR→PCX. Longest prefix match."},{"id":"s3","type":"lesson","title":"Best Practices","content":"Separate tables per tier. Descriptive tags. Two per AZ (public+private). Document propagation. VPC Flow Logs. Transit Gateway for complex setups."},{"id":"s4","type":"quiz","question":"Which route wins when multiple match?","options":["Longest prefix","Shortest prefix","Alphabetical","Random"],"correct":0,"explanation":"Most specific CIDR (longest prefix) wins."},{"id":"s5","type":"exercise","title":"Route Config","description":"Public ALB + private app subnets. Routes, targets, associations. Outbound internet via NAT."}] },
  { id:"c44", title:"Internet Gateways", titleBn:"ইন্টারনেট গেটওয়ে", part:"Networking", sections:[{"id":"s1","type":"lesson","title":"IGW Fundamentals","content":"Redundant, HA component for internet. Performs NAT for public IPs. One per VPC. Free (data transfer only)."},{"id":"s2","type":"lesson","title":"IGW Architecture","content":"Create, attach to VPC, route 0.0.0.0/0→IGW. One-to-one NAT private→public. No stateful inspection. Omit route to block internet."},{"id":"s3","type":"lesson","title":"IGW vs NAT vs Egress-Only","content":"IGW: bidirectional, public resources. NAT Gateway: outbound-only, ~$0.045/hr. Egress-Only IGW: outbound-only IPv6, free."},{"id":"s4","type":"quiz","question":"Can IGW attach to multiple VPCs?","options":["Yes","No","Up to 2","Up to 5"],"correct":1,"explanation":"One IGW per VPC."},{"id":"s5","type":"exercise","title":"Internet Design","description":"Public web + private app servers. IGW, NAT Gateway placement, route tables, HA."}] },
  { id:"c45", title:"NAT Gateways", titleBn:"NAT গেটওয়ে", part:"Networking", sections:[{"id":"s1","type":"lesson","title":"NAT Gateway Overview","content":"Outbound internet for private subnets. Managed, HA within AZ. Elastic IP in public subnet. $0.045/hr + $0.045/GB. One per AZ for HA."},{"id":"s2","type":"lesson","title":"Configuration","content":"Create in public subnet with EIP. Route 0.0.0.0/0→NAT ID in private RT. Multi-AZ: one per AZ, each RT points to local NAT. 5 Gbps (burst 10)."},{"id":"s3","type":"lesson","title":"NAT Gateway vs Instance","content":"NAT Gateway (managed): no patches, auto-scales 45 Gbps, auto-failover. NAT Instance (EC2): can be bastion, IPSec, free (EC2 cost)."},{"id":"s4","type":"quiz","question":"NAT Gateways for multi-AZ HA?","options":["1","1/Region","1/AZ","2/AZ"],"correct":2,"explanation":"Deploy one NAT Gateway per AZ."},{"id":"s5","type":"exercise","title":"NAT HA Design","description":"3-AZ VPC with private subnets. NAT placement, routing, failover, cost optimization."}] },
  { id:"c46", title:"Security Groups", titleBn:"সিকিউরিটি গ্রুপ", part:"Networking", sections:[{"id":"s1","type":"lesson","title":"SG Overview","content":"Instance-level virtual firewall. Stateful (return traffic auto-allowed). Default: deny inbound, allow outbound. Only allow rules. Multiple SGs per instance."},{"id":"s2","type":"lesson","title":"Rule Types","content":"Type (SSH, HTTP, custom), Protocol (TCP/UDP/ICMP), Port Range, Source (CIDR, SG ID, prefix list). SSH from office IP only. App port from ALB SG."},{"id":"s3","type":"lesson","title":"Design Patterns","content":"Layered security (multiple SGs). Self-referencing for cluster. Bastion→App. ALB→Backend. Database→App only."},{"id":"s4","type":"quiz","question":"Are SGs stateful?","options":["Stateful","Stateless","Configurable","Depends"],"correct":0,"explanation":"SGs are stateful—return traffic auto-allowed."},{"id":"s5","type":"exercise","title":"SG Rules Design","description":"3-tier: ALB, Node.js (3000), PostgreSQL (5432). Inbound rules with sources."}] },
  { id:"c47", title:"Network ACLs", titleBn:"নেটওয়ার্ক ACL", part:"Networking", sections:[{"id":"s1","type":"lesson","title":"NACL Overview","content":"Subnet-level stateless firewall. Numbered rules (lowest first). Separate in/outbound. Allow + Deny. Default allows all, custom denies all."},{"id":"s2","type":"lesson","title":"Rule Evaluation","content":"First matching rule wins. Incremental numbering (100,200,300). Must allow ephemeral ports (1024-65535) for TCP return traffic."},{"id":"s3","type":"lesson","title":"SG vs NACL","content":"Stateful (SG) vs Stateless (NACL). Instance vs Subnet. Allow only vs Allow+Deny. SG reference vs CIDR only. NACLs for explicit deny."},{"id":"s4","type":"quiz","question":"Are NACLs stateful?","options":["Stateful","Stateless","Configurable","Both"],"correct":1,"explanation":"NACLs are stateless."},{"id":"s5","type":"exercise","title":"NACL Design","description":"Public web + private app subnets. Inbound HTTP/HTTPS, SSH from office, ephemeral ports, deny malicious CIDRs."}] },
  { id:"c48", title:"Route 53", titleBn:"রুট ৫৩", part:"Networking", sections:[{"id":"s1","type":"lesson","title":"Route 53 Overview","content":"Highly available DNS. Functions: domain registration, DNS routing, health checking. Record types: A, AAAA, CNAME, MX, TXT, NS, Alias (AWS resources)."},{"id":"s2","type":"lesson","title":"Routing Policies","content":"Simple, Weighted (A/B testing), Latency-based, Failover (active-passive), Geolocation, Geoproximity, Multi-value, IP-based."},{"id":"s3","type":"lesson","title":"Health Checks","content":"Endpoint (HTTP/HTTPS/TCP), Calculated (combine), CloudWatch (alarm). Interval 10/30s, failure threshold, string matching. DNS failover."},{"id":"s4","type":"quiz","question":"Which policy routes to lowest-latency Region?","options":["Simple","Weighted","Latency-based","Geolocation"],"correct":2,"explanation":"Latency-based routing to lowest-latency Region."},{"id":"s5","type":"exercise","title":"DNS Strategy","description":"Global app in us-east-1 + eu-west-1. Latency + weighted (5% canary) + health checks."}] },
  { id:"c49", title:"CloudFront CDN", titleBn:"ক্লাউডফ্রন্ট CDN", part:"Networking", sections:[{"id":"s1","type":"lesson","title":"CloudFront Overview","content":"CDN with 600+ edges. HTTPS, ACM, geo-restriction, Shield, Lambda@Edge, Origin Groups, WAF, OAC for S3."},{"id":"s2","type":"lesson","title":"Behaviors and Caching","content":"Path patterns, origin (S3/ALB/custom), TTL (0s-1yr), query/cookie/header handling. Signed URLs for private content."},{"id":"s3","type":"lesson","title":"Security and Optimization","content":"OAC for S3. WAF integration. Shield Advanced. Field-level encryption. Geo-restriction. Compression. HTTP/2, HTTP/3."},{"id":"s4","type":"quiz","question":"How does CloudFront secure S3 access?","options":["IAM roles","OAC/OAI","SGs","Bucket policies"],"correct":1,"explanation":"CloudFront uses OAC (or OAI) for S3 origin access."},{"id":"s5","type":"exercise","title":"CDN Design","description":"Global media: S3 for static, ALB for API, geo-restriction, custom domain, HTTPS."}] },
  { id:"c50", title:"API Gateway", titleBn:"API গেটওয়ে", part:"Networking", sections:[{"id":"s1","type":"lesson","title":"API Gateway Overview","content":"Managed API service. Types: REST (full), HTTP (simpler), WebSocket (real-time). Features: API keys, throttling, caching, CORS, Cognito auth."},{"id":"s2","type":"lesson","title":"Endpoint Types","content":"Edge-optimized (global), Regional (same-Region), Private (VPC). Auth: IAM (Sig v4), Cognito (JWT), Lambda authorizers, API keys."},{"id":"s3","type":"lesson","title":"Integration and Monitoring","content":"Lambda, HTTP, AWS Service, Mock, VPC Link. CloudWatch metrics (4XX/5XX, latency), logs, X-Ray. Caching (300-3600s TTL)."},{"id":"s4","type":"quiz","question":"Best for real-time communication?","options":["REST","HTTP","WebSocket","Private"],"correct":2,"explanation":"WebSocket APIs maintain persistent connections."},{"id":"s5","type":"exercise","title":"API Design","description":"Serverless e-commerce: CRUD, Cognito auth, Step Functions orders, admin API keys."}] },
  { id:"c51", title:"CI/CD Basics", titleBn:"CI/CD বেসিক", part:"DevOps + Automation", sections:[{"id":"s1","type":"lesson","title":"CI/CD Concepts","content":"CI: frequent merges with automated builds/tests. CD: automated build, test, prepare for release. Continuous Delivery (manual approval) vs Deployment (fully auto)."},{"id":"s2","type":"lesson","title":"AWS CI/CD Services","content":"CodeCommit (Git), CodeBuild (build/test), CodeDeploy (deploy), CodePipeline (orchestrate), CodeStar (dashboard)."},{"id":"s3","type":"lesson","title":"Pipeline Stages","content":"Source (CodeCommit/GitHub/S3), Build (CodeBuild), Deploy (CodeDeploy). Quality gates: manual approval, tests, security scanning."},{"id":"s4","type":"quiz","question":"Which orchestrates CI/CD?","options":["CodeBuild","CodeDeploy","CodePipeline","CodeCommit"],"correct":2,"explanation":"CodePipeline orchestrates CI/CD workflows."},{"id":"s5","type":"exercise","title":"Pipeline Design","description":"Node.js: GitHub source → CodeBuild → CodeDeploy to EC2. Include quality gates."}] },
  { id:"c52", title:"CodePipeline", titleBn:"কোডপাইপলাইন", part:"DevOps + Automation", sections:[{"id":"s1","type":"lesson","title":"CodePipeline Overview","content":"Fully managed CI/CD. Sources: GitHub, CodeCommit, S3, ECR. Integrates: CodeBuild, CodeDeploy, CloudFormation, Elastic Beanstalk, Lambda, ECS."},{"id":"s2","type":"lesson","title":"Pipeline Structure","content":"Stages (Source, Build, Test, Deploy) with actions (parallel/sequential). Artifacts in S3. Manual approval gates. Stage execution history."},{"id":"s3","type":"lesson","title":"Best Practices","content":"Version control pipeline definition. Environment-specific actions. Notifications for failures. Encryption for artifacts. Approval gates for production."},{"id":"s4","type":"quiz","question":"Where are artifacts stored?","options":["ECR","S3","EBS","DynamoDB"],"correct":1,"explanation":"Artifacts stored in S3."},{"id":"s5","type":"exercise","title":"Pipeline Creation","description":"GitHub → CodeBuild (npm build+test) → manual approval → CodeDeploy to ECS Fargate."}] },
  { id:"c53", title:"CodeBuild", titleBn:"কোডবিল্ড", part:"DevOps + Automation", sections:[{"id":"s1","type":"lesson","title":"CodeBuild Overview","content":"Managed build service. Supports Java, Python, Node.js, Go, .NET, Ruby. Pay per build minute. No build servers. Integrates with CodePipeline."},{"id":"s2","type":"lesson","title":"buildspec.yml","content":"Phases: install, pre_build, build, post_build. Env vars, secrets, reports, cache. S3 artifacts or ECR images."},{"id":"s3","type":"lesson","title":"Environment Types","content":"Managed (Ubuntu, Windows, Amazon Linux). Custom (Docker in ECR). GPU for ML. Compute: 3GB/2vCPU to 72GB/32vCPU. Local caching."},{"id":"s4","type":"quiz","question":"Which file defines build phases?","options":["package.json","Dockerfile","buildspec.yml","Makefile"],"correct":2,"explanation":"buildspec.yml defines CodeBuild phases."},{"id":"s5","type":"exercise","title":"Build Spec","description":"buildspec.yml for Node.js: npm install, test, build, upload artifacts to S3."}] },
  { id:"c54", title:"CodeDeploy", titleBn:"কোডডিপ্লয়", part:"DevOps + Automation", sections:[{"id":"s1","type":"lesson","title":"CodeDeploy Overview","content":"Automated deployment to EC2, Lambda, ECS, on-premises. In-place (rolling) and blue/green. appspec.yml defines actions."},{"id":"s2","type":"lesson","title":"Deployment Types","content":"In-place: update existing instances, gradual. Blue/green: new environment, traffic switch. Zero-downtime. Lambda: canary/linear traffic shifts."},{"id":"s3","type":"lesson","title":"AppSpec File","content":"For EC2: files, permissions, hooks (BeforeInstall, AfterInstall, ApplicationStart). For Lambda: function, version, traffic config. For ECS: task definition, LB info."},{"id":"s4","type":"quiz","question":"Which file defines CodeDeploy actions?","options":["buildspec.yml","appspec.yml","Dockerfile","deploy.sh"],"correct":1,"explanation":"appspec.yml defines CodeDeploy actions."},{"id":"s5","type":"exercise","title":"Deployment Design","description":"Blue/green ECS Fargate: 10% every 5 min, rollback on CloudWatch alarm."}] },
  { id:"c55", title:"CloudFormation", titleBn:"ক্লাউডফর্মেশন", part:"DevOps + Automation", sections:[{"id":"s1","type":"lesson","title":"CloudFormation Overview","content":"IaC service. Define resources in YAML/JSON. Automated provisioning as stacks. Drift detection, change sets, stack sets. Free (pay for resources)."},{"id":"s2","type":"lesson","title":"Template Structure","content":"AWSTemplateFormatVersion, Description, Parameters, Mappings, Conditions, Resources (required), Outputs."},{"id":"s3","type":"lesson","title":"Stack Operations","content":"Create (parallel provision). Update (change detection). Delete (remove all). Change sets preview changes."},{"id":"s4","type":"quiz","question":"Required template section?","options":["Parameters","Resources","Outputs","Mappings"],"correct":1,"explanation":"Resources is required."},{"id":"s5","type":"exercise","title":"CloudFormation Template","description":"YAML template: VPC, public/private subnets, IGW, EC2 instance."}] },
  { id:"c56", title:"Terraform Basics", titleBn:"টেরাফর্ম বেসিক", part:"DevOps + Automation", sections:[{"id":"s1","type":"lesson","title":"Terraform Overview","content":"Open-source IaC by HashiCorp. HCL language. Multi-cloud (AWS, Azure, GCP). State files. Plan/Apply workflow. Modules."},{"id":"s2","type":"lesson","title":"Terraform vs CloudFormation","content":"Terraform: multi-cloud, HCL, state, modules from registry. CloudFormation: AWS-only, YAML/JSON, native integration, stack sets. Choose based on needs."},{"id":"s3","type":"lesson","title":"Resources and Providers","content":"Provider block (AWS config). Resource block (aws_vpc, aws_subnet). Data sources query existing. Variables and outputs."},{"id":"s4","type":"quiz","question":"Terraform language?","options":["YAML","JSON","HCL","TOML"],"correct":2,"explanation":"Terraform uses HCL."},{"id":"s5","type":"exercise","title":"Terraform Config","description":"VPC with public subnet, IGW, EC2 in us-east-1."}] },
  { id:"c57", title:"Infrastructure as Code", titleBn:"ইনফ্রাস্ট্রাকচার অ্যাজ কোড", part:"DevOps + Automation", sections:[{"id":"s1","type":"lesson","title":"IaC Principles","content":"Manage infrastructure via definition files. Benefits: repeatability, version control, automation, consistency. Immutable infrastructure. Idempotent deployments."},{"id":"s2","type":"lesson","title":"AWS IaC Tools","content":"CloudFormation (YAML/JSON). CDK (TypeScript/Python/Java/C#, compiles to CloudFormation). Elastic Beanstalk. OpsWorks. Systems Manager."},{"id":"s3","type":"lesson","title":"Best Practices","content":"Version control all templates. Parameterize environments. Modular design. Test in dev. Use change sets/plans. Drift detection for CloudFormation."},{"id":"s4","type":"quiz","question":"Which compiles code to CloudFormation?","options":["CDK","CloudFormation","Terraform","Elastic Beanstalk"],"correct":0,"explanation":"AWS CDK compiles code to CloudFormation."},{"id":"s5","type":"exercise","title":"IaC Strategy","description":"Multi-environment deployment (dev/staging/prod) with CloudFormation or Terraform + CI/CD."}] },
  { id:"c58", title:"Docker on AWS", titleBn:"AWS-এ ডকার", part:"DevOps + Automation", sections:[{"id":"s1","type":"lesson","title":"Docker Overview","content":"Container platform. Images (read-only) → Containers (running). Dockerfile defines build. Benefits: consistency, isolation, lightweight, microservices."},{"id":"s2","type":"lesson","title":"AWS Container Services","content":"ECS (Fargate/EC2). EKS (managed Kubernetes). ECR (image registry). App Mesh (service mesh). Copilot (CLI)."},{"id":"s3","type":"lesson","title":"Dockerfile Best Practices","content":"Multi-stage builds. Specific base versions. Minimize layers. .dockerignore. Non-root user. Image scanning. Tag with Git commit hash."},{"id":"s4","type":"quiz","question":"Which service is a Docker registry?","options":["ECS","EKS","ECR","Fargate"],"correct":2,"explanation":"ECR is a managed Docker container registry."},{"id":"s5","type":"exercise","title":"Containerize App","description":"Dockerfile for Node.js Express, push to ECR, deploy to ECS Fargate."}] },
  { id:"c59", title:"Kubernetes on AWS", titleBn:"AWS-এ কুবারনেটিস", part:"DevOps + Automation", sections:[{"id":"s1","type":"lesson","title":"EKS Overview","content":"Managed Kubernetes. AWS-managed control plane. Worker nodes: managed node groups, Fargate, or self-managed. EKS-D for on-premises."},{"id":"s2","type":"lesson","title":"EKS Architecture","content":"Control plane in AWS VPC. Worker nodes in your VPC. VPC CNI for pod networking. IRSA for IAM. Cluster Autoscaler or Karpenter."},{"id":"s3","type":"lesson","title":"Best Practices","content":"IRSA for pod permissions. EBS CSI driver. ALB Ingress Controller. Cluster Autoscaler/Karpenter. Secrets Manager CSI driver. NodeLocal DNSCache."},{"id":"s4","type":"quiz","question":"EKS pod networking plugin?","options":["Flannel","Calico","AWS VPC CNI","Weave"],"correct":2,"explanation":"EKS uses AWS VPC CNI giving each pod a VPC IP."},{"id":"s5","type":"exercise","title":"EKS Design","description":"Fargate for stateless, managed node groups for stateful, ALB Ingress, IRSA for DynamoDB."}] },
  { id:"c60", title:"Serverless Architectures", titleBn:"সার্ভারলেস আর্কিটেকচার", part:"DevOps + Automation", sections:[{"id":"s1","type":"lesson","title":"Serverless Overview","content":"No server management. Key: Lambda (compute), API Gateway (API), DynamoDB (DB), S3 (storage), SQS/SNS (messaging), Step Functions (orchestration)."},{"id":"s2","type":"lesson","title":"Serverless Patterns","content":"Event-driven (S3→Lambda→DynamoDB). Fan-out (SNS→SQS). Web API (API Gateway→Lambda→DynamoDB). Stream (Kinesis→Lambda)."},{"id":"s3","type":"lesson","title":"Best Practices","content":"Step Functions for complex workflows. DLQ for failures. Idempotency. Provisioned Concurrency. X-Ray tracing. Small focused functions."},{"id":"s4","type":"quiz","question":"Which orchestrates serverless workflows?","options":["Lambda","Step Functions","API Gateway","SQS"],"correct":1,"explanation":"Step Functions orchestrates serverless workflows."},{"id":"s5","type":"exercise","title":"Serverless Architecture","description":"Image processing: S3 upload → Lambda thumbnail → DynamoDB metadata → CloudFront CDN."}] },
  { id:"c61", title:"CloudWatch Basics", titleBn:"ক্লাউডওয়াচ বেসিক", part:"Monitoring + Optimization", sections:[{"id":"s1","type":"lesson","title":"CloudWatch Overview","content":"Monitoring service. Metrics (CPU, memory, custom), Logs (collect/store), Alarms (threshold actions), Dashboards (custom), EventBridge (event-driven)."},{"id":"s2","type":"lesson","title":"CloudWatch Metrics","content":"Default (EC2 CPU, RDS connections) and custom. Namespaces, dimensions, timestamps. 15-month retention."},{"id":"s3","type":"lesson","title":"CloudWatch Alarms","content":"Monitor metrics, trigger actions (SNS, Auto Scaling, EC2 actions). States: OK, ALARM, INSUFFICIENT_DATA. Composite alarms."},{"id":"s4","type":"quiz","question":"What triggers alarm actions?","options":["Metric threshold","Log pattern","API call","Schedule"],"correct":0,"explanation":"Alarms trigger when metric crosses threshold."},{"id":"s5","type":"exercise","title":"CloudWatch Setup","description":"Dashboard: CPU, memory, request count, errors. Alarm CPU >80% → Auto Scaling."}] },
  { id:"c62", title:"Logging and Metrics", titleBn:"লগিং এবং মেট্রিক্স", part:"Monitoring + Optimization", sections:[{"id":"s1","type":"lesson","title":"Centralized Logging","content":"Aggregate logs from services. CloudWatch Logs from EC2 (agent), Lambda, VPC Flow Logs, CloudTrail, RDS. Log groups/streams. Metric filters."},{"id":"s2","type":"lesson","title":"Logs Insights","content":"SQL-like query for log analysis. Multiple log groups. Filter, aggregate, sort, visualize. Troubleshooting, latency analysis, pattern detection."},{"id":"s3","type":"lesson","title":"Retention and Export","content":"Per log group retention (1 day to 10 years). Export to S3 via ExportTask or Lambda subscription. S3 lifecycle to Glacier."},{"id":"s4","type":"quiz","question":"Which tool queries CloudWatch Logs?","options":["Athena","Logs Insights","QuickSight","Redshift"],"correct":1,"explanation":"Logs Insights provides SQL-like log querying."},{"id":"s5","type":"exercise","title":"Logging Strategy","description":"Centralized: EC2 logs, RDS errors, ALB access. 90 days CloudWatch, 1 year S3."}] },
  { id:"c63", title:"CloudTrail", titleBn:"ক্লাউডট্রেইল", part:"Monitoring + Optimization", sections:[{"id":"s1","type":"lesson","title":"CloudTrail Overview","content":"Records API activity. Who, what service, when, source IP, response. Free 90-day retention for management events. Trails to S3/CloudWatch."},{"id":"s2","type":"lesson","title":"Event Types","content":"Management events (CreateVPC, TerminateInstance). Data events (S3 GetObject, Lambda Invoke). Insights (anomalous activity)."},{"id":"s3","type":"lesson","title":"Best Practices","content":"Enable in all Regions. Multi-Region trail. Centralized S3 with MFA delete. Log validation. CloudWatch for real-time. Security alerts."},{"id":"s4","type":"quiz","question":"What does CloudTrail record?","options":["Network traffic","API calls","CPU usage","Memory"],"correct":1,"explanation":"CloudTrail records API activity."},{"id":"s5","type":"exercise","title":"CloudTrail Setup","description":"Multi-Region trail to S3 with validation and CloudWatch integration."}] },
  { id:"c64", title:"X-Ray Tracing", titleBn:"X-রে ট্রেসিং", part:"Monitoring + Optimization", sections:[{"id":"s1","type":"lesson","title":"X-Ray Overview","content":"Distributed tracing. Traces requests end-to-end. Identifies bottlenecks. Works with Lambda, EC2, ECS, API Gateway."},{"id":"s2","type":"lesson","title":"X-Ray Concepts","content":"Trace (end-to-end path), Segment (compute resource), Subsegment (downstream call), Service graph (visual map), Annotations (indexed), Metadata."},{"id":"s3","type":"lesson","title":"SDK Integration","content":"Install X-Ray SDK (Node.js, Python, Java, Go, .NET). Instrument requests and downstream calls. X-Ray daemon for EC2. Lambda built-in."},{"id":"s4","type":"quiz","question":"What does X-Ray trace?","options":["Logs","Metrics","Requests","Config"],"correct":2,"explanation":"X-Ray traces requests through applications."},{"id":"s5","type":"exercise","title":"X-Ray Instrumentation","description":"API Gateway → Lambda → DynamoDB. Trace segments, annotations for user ID, subsegments for DB calls."}] },
  { id:"c65", title:"Cost Explorer", titleBn:"কস্ট এক্সপ্লোরার", part:"Monitoring + Optimization", sections:[{"id":"s1","type":"lesson","title":"Cost Explorer Overview","content":"Visualize costs and usage. Custom reports. Filter by service, Region, account, tag. Forecast. RI/Savings Plans recommendations."},{"id":"s2","type":"lesson","title":"Cost Analysis","content":"Hourly/daily/monthly granularity. Filter by tags (Environment, Project). Group by service/Region. Chargeback reports. RI utilization."},{"id":"s3","type":"lesson","title":"AWS Budgets","content":"Cost budget (monthly amount). Usage budget (service usage). RI/Savings Plans budgets. Alerts via SNS/email."},{"id":"s4","type":"quiz","question":"What does Budgets monitor?","options":["Performance","Security","Cost and usage","Compliance"],"correct":2,"explanation":"Budgets monitors costs and usage."},{"id":"s5","type":"exercise","title":"Cost Monitoring","description":"Budget $500/month. Alerts at 50%, 80%, 90%, 100%. Tag allocation for Project/Environment."}] },
  { id:"c66", title:"Trusted Advisor", titleBn:"ট্রাস্টেড অ্যাডভাইজার", part:"Monitoring + Optimization", sections:[{"id":"s1","type":"lesson","title":"Trusted Advisor Overview","content":"Real-time guidance for cost, performance, security, fault tolerance, service limits. Core checks free. Full with Business/Enterprise support."},{"id":"s2","type":"lesson","title":"Check Categories","content":"Cost: idle resources, RI optimization. Performance: EBS throughput, CloudFront SSL. Security: SG ports, MFA on root, S3 permissions. FT: Multi-AZ, backups. Limits."},{"id":"s3","type":"lesson","title":"Automation","content":"Support API for check results. Systems Manager auto-remediation. Weekly emails. Security Hub integration. EventBridge + Lambda."},{"id":"s4","type":"quiz","question":"Plan for full TA checks?","options":["Basic","Developer","Business","All"],"correct":2,"explanation":"Full checks with Business/Enterprise support."},{"id":"s5","type":"exercise","title":"TA Review","description":"Action plan: idle RDS, unrestricted SG ports, IAM key rotation, underutilized EC2."}] },
  { id:"c67", title:"Performance Optimization", titleBn:"পারফরম্যান্স অপ্টিমাইজেশন", part:"Monitoring + Optimization", sections:[{"id":"s1","type":"lesson","title":"Compute Optimization","content":"Right-size with CloudWatch + Compute Optimizer. Graviton instances. Enhanced Networking. Auto Scaling. Spot for flexible."},{"id":"s2","type":"lesson","title":"Storage Performance","content":"gp3 for most, io2 for databases. Transfer Acceleration. CloudFront. ElastiCache. DynamoDB DAX."},{"id":"s3","type":"lesson","title":"Database Optimization","content":"Read replicas. RDS Proxy. Index optimization. Performance Insights. Aurora for higher performance."},{"id":"s4","type":"quiz","question":"Which service recommends right-sizing?","options":["Trusted Advisor","Compute Optimizer","Cost Explorer","CloudWatch"],"correct":1,"explanation":"Compute Optimizer recommends optimal instance types."},{"id":"s5","type":"exercise","title":"Performance Audit","description":"Right-size EC2, CloudFront for static, RDS read replicas, DAX for hot data."}] },
  { id:"c68", title:"Scaling Strategies", titleBn:"স্কেলিং স্ট্র্যাটেজি", part:"Monitoring + Optimization", sections:[{"id":"s1","type":"lesson","title":"Horizontal vs Vertical","content":"Horizontal: more instances, near-limitless, better FT. Vertical: bigger instance, max limit. Cloud-native favors horizontal."},{"id":"s2","type":"lesson","title":"Database Scaling","content":"Read replicas (scale reads). Sharding. DynamoDB auto-scales. RDS Proxy. ElastiCache. Aurora Auto Scaling."},{"id":"s3","type":"lesson","title":"Global Scaling","content":"CloudFront. Multi-Region. Route 53 latency routing. Global Accelerator. DynamoDB Global Tables. Aurora Global Database."},{"id":"s4","type":"quiz","question":"Cloud-native scaling preference?","options":["Vertical","Horizontal","Diagonal","Manual"],"correct":1,"explanation":"Horizontal scaling for limitless scale and fault tolerance."},{"id":"s5","type":"exercise","title":"Scaling Plan","description":"Global e-commerce for Black Friday (10x traffic). Use all scaling techniques."}] },
  { id:"c69", title:"Disaster Recovery", titleBn:"ডিজাস্টার রিকভারি", part:"Monitoring + Optimization", sections:[{"id":"s1","type":"lesson","title":"DR Concepts","content":"RTO (max downtime), RPO (max data loss). Strategies: Backup/Restore (high RTO/RPO), Pilot Light (minimal), Warm Standby (scaled copy), Multi-Site (active/active)."},{"id":"s2","type":"lesson","title":"AWS DR Services","content":"S3/Glacier for backups. RDS point-in-time + cross-Region replicas. DynamoDB global tables + backups. CloudFormation. Route 53 failover."},{"id":"s3","type":"lesson","title":"DR Planning","content":"Define RTO/RPO per workload. Automate failover. Test regularly with FIS. Document runbooks. Balance cost vs recovery requirements."},{"id":"s4","type":"quiz","question":"Lowest cost DR strategy?","options":["Multi-Site","Warm Standby","Pilot Light","Backup and Restore"],"correct":3,"explanation":"Backup/Restore lowest cost, highest RTO/RPO."},{"id":"s5","type":"exercise","title":"DR Plan","description":"Critical DB: RPO 15min, RTO 1hr. RDS cross-Region replica, CloudFormation, Route 53 failover."}] },
  { id:"c70", title:"High Availability", titleBn:"হাই অ্যাভেইলেবিলিটি", part:"Monitoring + Optimization", sections:[{"id":"s1","type":"lesson","title":"HA Principles","content":"Eliminate SPOF. Multi-AZ. Health checks + auto-failover. Design for failure. Loosely coupled. Stateless apps."},{"id":"s2","type":"lesson","title":"Multi-AZ Architecture","content":"ALB across AZs. ASG across AZs. RDS Multi-AZ. ElastiCache Multi-AZ. NAT per AZ. Subnets across AZs."},{"id":"s3","type":"lesson","title":"HA Patterns","content":"Active-passive (RDS Multi-AZ). Active-active (ALB + multi-AZ). Shuffle sharding. Throttling. Graceful degradation."},{"id":"s4","type":"quiz","question":"Which eliminates SPOF?","options":["Vertical scaling","Single AZ","Multi-AZ","Manual failover"],"correct":2,"explanation":"Multi-AZ eliminates single points of failure."},{"id":"s5","type":"exercise","title":"HA Architecture","description":"99.99% web app: multi-AZ, ALB, ASG, RDS Multi-AZ, ElastiCache, health checks."}] },
  { id:"c71", title:"Static Website on S3", titleBn:"S3-এ স্ট্যাটিক ওয়েবসাইট", part:"Real-World Cloud Projects", sections:[{"id":"s1","type":"lesson","title":"Project Overview","content":"Host static website (HTML/CSS/JS) on S3 with CloudFront, custom domain via Route 53, HTTPS via ACM."},{"id":"s2","type":"lesson","title":"Implementation","content":"Create S3 bucket (block public). Upload files. Enable hosting. Bucket policy for CloudFront OAC. CloudFront distribution. Route 53 alias. ACM cert."},{"id":"s3","type":"lesson","title":"Best Practices","content":"CloudFront OAC for security. Compression. Cache TTLs. Versioned files for cache busting. Error pages. CloudFront logs."},{"id":"s4","type":"quiz","question":"Which service is the CDN?","options":["S3","CloudFront","Route 53","ACM"],"correct":1,"explanation":"CloudFront provides CDN."},{"id":"s5","type":"exercise","title":"Deploy Site","description":"Deploy resume: S3 bucket, upload, CloudFront with custom domain and HTTPS."}] },
  { id:"c72", title:"Build Serverless API", titleBn:"সার্ভারলেস API", part:"Real-World Cloud Projects", sections:[{"id":"s1","type":"lesson","title":"Project Overview","content":"Serverless REST API with API Gateway, Lambda, DynamoDB for notes app."},{"id":"s2","type":"lesson","title":"Implementation","content":"DynamoDB table (userId PK, noteId SK). CRUD Lambda functions. API Gateway REST API. CORS. Deploy."},{"id":"s3","type":"lesson","title":"Security","content":"Lambda authorizer with JWT (Cognito). Usage plans. Throttling. CloudWatch logging. X-Ray. KMS encryption."},{"id":"s4","type":"quiz","question":"Database for serverless API?","options":["RDS","DynamoDB","Redshift","ElastiCache"],"correct":1,"explanation":"DynamoDB is the serverless NoSQL database."},{"id":"s5","type":"exercise","title":"Build API","description":"DynamoDB table, CRUD Lambdas, API Gateway, Cognito auth, deploy and test."}] },
  { id:"c73", title:"Fullstack App Deployment", titleBn:"ফুলস্ট্যাক অ্যাপ ডিপ্লয়", part:"Real-World Cloud Projects", sections:[{"id":"s1","type":"lesson","title":"Project Overview","content":"React frontend (S3/CloudFront), Node.js backend (ECS Fargate), PostgreSQL (RDS), domain (Route 53)."},{"id":"s2","type":"lesson","title":"Architecture","content":"React → S3/CloudFront. Express API → ECS Fargate + ALB. PostgreSQL → RDS Multi-AZ. CodePipeline for CI/CD."},{"id":"s3","type":"lesson","title":"Deployment Steps","content":"RDS setup. ECS cluster + task definition. Docker build + push to ECR. ECS service with ALB. React build + S3 upload. CloudFront. Route 53. CI/CD."},{"id":"s4","type":"quiz","question":"Where does Node.js backend run?","options":["Lambda","ECS Fargate","EC2","Elastic Beanstalk"],"correct":1,"explanation":"Node.js on ECS Fargate."},{"id":"s5","type":"exercise","title":"Fullstack Deploy","description":"React + Node.js + PostgreSQL. S3/CloudFront, ECS Fargate, RDS, CodePipeline."}] },
  { id:"c74", title:"Auto Scaling Web App", titleBn:"অটো স্কেলিং ওয়েব অ্যাপ", part:"Real-World Cloud Projects", sections:[{"id":"s1","type":"lesson","title":"Project Overview","content":"Web app with ASG, ELB, health checks. Scaling policies, launch templates, monitoring. Handle traffic spikes."},{"id":"s2","type":"lesson","title":"Architecture","content":"ALB in public subnets. ASG across 3 AZs. Launch Template (Amazon Linux 2). Target tracking (50% CPU). Lifecycle hooks."},{"id":"s3","type":"lesson","title":"Testing","content":"Load testing with artillery. Monitor ASG activities. CloudWatch metrics. Dashboards. Notifications. Failover testing."},{"id":"s4","type":"quiz","question":"What triggers ASG to add instances?","options":["Manual","Scheduled","CloudWatch alarm","API call"],"correct":2,"explanation":"CloudWatch alarms trigger ASG scaling."},{"id":"s5","type":"exercise","title":"ASG Setup","description":"ALB, launch template, target tracking 50% CPU, min 2 max 10, 3 AZs. Test with load generator."}] },
  { id:"c75", title:"CI/CD Pipeline", titleBn:"CI/CD পাইপলাইন", part:"Real-World Cloud Projects", sections:[{"id":"s1","type":"lesson","title":"Project Overview","content":"Complete CI/CD with CodePipeline, CodeBuild, CodeDeploy. Canary deployments with traffic shifting."},{"id":"s2","type":"lesson","title":"Pipeline Stages","content":"GitHub → CodePipeline. CodeBuild (npm install, test, build). CodeDeploy (staging ECS). Integration tests. Manual approval. Production canary."},{"id":"s3","type":"lesson","title":"Deployment Strategy","content":"Blue/green ECS. Traffic shifting: 10% initially, 5 min observation, 50%, 100%. Rollback on failure."},{"id":"s4","type":"quiz","question":"Which deployment shifts traffic gradually?","options":["In-place","Blue/green","Canary","Rolling"],"correct":2,"explanation":"Canary shifts traffic incrementally."},{"id":"s5","type":"exercise","title":"Build Pipeline","description":"GitHub → CodeBuild (Docker) → CodeDeploy (ECS blue/green canary) → approval → production."}] },
  { id:"c76", title:"CloudWatch Dashboard", titleBn:"ক্লাউডওয়াচ ড্যাশবোর্ড", part:"Real-World Cloud Projects", sections:[{"id":"s1","type":"lesson","title":"Project Overview","content":"Comprehensive CloudWatch dashboard for health, performance, cost. Logs, metrics, alarms, proactive notifications."},{"id":"s2","type":"lesson","title":"Dashboard Widgets","content":"EC2 (CPU, memory, disk, network). ALB (requests, latency, 5XX). RDS (connections, IOPS, lag). Lambda (invocations, errors, duration). Cost."},{"id":"s3","type":"lesson","title":"Automated Responses","content":"Alarms for key metrics. Systems Manager Automation + Lambda auto-remediation. SNS to email/Slack. Composite alarms. OpsItems."},{"id":"s4","type":"quiz","question":"Which service creates dashboards?","options":["CloudWatch","CloudTrail","Config","X-Ray"],"correct":0,"explanation":"CloudWatch Dashboards create monitoring views."},{"id":"s5","type":"exercise","title":"Build Dashboard","description":"CPU, ALB requests, RDS connections, Lambda errors, cost widget. Alarms with SNS."}] },
  { id:"c77", title:"Secure Enterprise Architecture", titleBn:"সিকিউর এন্টারপ্রাইজ আর্কিটেকচার", part:"Real-World Cloud Projects", sections:[{"id":"s1","type":"lesson","title":"Project Overview","content":"Secure enterprise architecture: VPC, SGs, NACLs, IAM, KMS, monitoring. Defense in depth."},{"id":"s2","type":"lesson","title":"Security Layers","content":"Network: VPC public/private, NACLs, SGs. Identity: IAM least privilege, MFA, permission boundaries. Data: KMS encryption. Monitoring: CloudTrail, GuardDuty, Security Hub, Config."},{"id":"s3","type":"lesson","title":"Compliance","content":"PCI DSS requirements. Audit logging. Encryption (AES-256). Access reviews. Incident response. Documentation."},{"id":"s4","type":"quiz","question":"Which aggregates security findings?","options":["GuardDuty","Security Hub","Inspector","Config"],"correct":1,"explanation":"Security Hub aggregates findings across accounts."},{"id":"s5","type":"exercise","title":"Security Architecture","description":"VPC isolation, IAM least privilege, KMS encryption, GuardDuty + Security Hub, CloudTrail + Config."}] },
  { id:"c78", title:"Multi-Region Deployment", titleBn:"মাল্টি-রিজিয়ন ডিপ্লয়মেন্ট", part:"Real-World Cloud Projects", sections:[{"id":"s1","type":"lesson","title":"Project Overview","content":"Deploy across Regions for DR and global latency. Active-active with Route 53 latency routing. Cross-Region replication."},{"id":"s2","type":"lesson","title":"Architecture","content":"Primary (us-east-1), Secondary (eu-west-1). Route 53 latency. DynamoDB Global Tables. S3 CRR. CloudFront. CloudFormation StackSets."},{"id":"s3","type":"lesson","title":"Failover Testing","content":"Simulate primary failure. Route 53 failover. Data consistency (RPO). Measure RTO. Lambda automation. Document runbook."},{"id":"s4","type":"quiz","question":"Which enables multi-Region DynamoDB writes?","options":["Read Replicas","Global Tables","DAX","Streams"],"correct":1,"explanation":"Global Tables provide multi-Region writes."},{"id":"s5","type":"exercise","title":"Multi-Region Deploy","description":"US + EU, StackSets, Global Tables, latency routing, S3 CRR, failover test."}] },
  { id:"c79", title:"Containerized Platform", titleBn:"কন্টেইনারাইজড প্ল্যাটফর্ম", part:"Real-World Cloud Projects", sections:[{"id":"s1","type":"lesson","title":"Project Overview","content":"Microservices platform on ECS Fargate, ECR, ALB, Service Discovery. Service mesh with App Mesh."},{"id":"s2","type":"lesson","title":"Architecture","content":"ALB → ECS services (api-gateway, user, order, payment). ECR. Cloud Map. App Mesh. X-Ray. CloudWatch."},{"id":"s3","type":"lesson","title":"CI/CD for Microservices","content":"Each service has independent CodePipeline. Monorepo with separate build contexts. ECR per service. Blue/green. Canary releases."},{"id":"s4","type":"quiz","question":"Which enables service mesh on ECS?","options":["Cloud Map","App Mesh","X-Ray","CloudWatch"],"correct":1,"explanation":"App Mesh provides service mesh."},{"id":"s5","type":"exercise","title":"Microservices Platform","description":"3 microservices on ECS Fargate with ALB, App Mesh, Cloud Map, X-Ray, independent CI/CD."}] },
  { id:"c80", title:"SaaS Architecture", titleBn:"SaaS আর্কিটেকচার", part:"Real-World Cloud Projects", sections:[{"id":"s1","type":"lesson","title":"Project Overview","content":"Multi-tenant SaaS on AWS. Tenant isolation, tiered pricing, usage metering, onboarding automation. 1000+ tenants."},{"id":"s2","type":"lesson","title":"Tenant Isolation Models","content":"Silo (separate resources, highest isolation). Pool (shared, lowest cost). Bridge (hybrid). Use IAM permissions boundaries and SCPs."},{"id":"s3","type":"lesson","title":"SaaS Operations","content":"Automated onboarding (CloudFormation). Usage metering (CloudWatch + Kinesis). Tiered pricing (API keys). Tenant dashboards. Data partitioning."},{"id":"s4","type":"quiz","question":"Highest security isolation model?","options":["Pool","Silo","Bridge","Hybrid"],"correct":1,"explanation":"Silo provides highest isolation with dedicated resources."},{"id":"s5","type":"exercise","title":"SaaS Design","description":"Silo for premium, pool for basic. Automated onboarding, usage metering, tiered pricing."}] },
  { id:"c81", title:"Cloud Practitioner Prep", titleBn:"AWS সার্টিফাইড ক্লাউড প্র্যাকটিশনার", part:"Certification + Advanced", sections:[{"id":"s1","type":"lesson","title":"Exam Overview","content":"CLF-C02: 90 min, 65 questions. Score 700/1000. Domains: Cloud Concepts 26%, Security 25%, Technology 33%, Billing 16%."},{"id":"s2","type":"lesson","title":"Key Topics","content":"Cloud models (IaaS/PaaS/SaaS). Global infrastructure. Well-Architected. Shared responsibility. Security services. Pricing models."},{"id":"s3","type":"lesson","title":"Study Resources","content":"Skill Builder digital courses. Whitepapers. Documentation. Practice exams. re:Invent videos. Ramp-Up Guides. 2-3 weeks study."},{"id":"s4","type":"quiz","question":"How long is Cloud Practitioner exam?","options":["60 min","90 min","120 min","180 min"],"correct":1,"explanation":"90 minutes with 65 questions."},{"id":"s5","type":"exercise","title":"Exam Prep","description":"Study plan: Well-Architected pillars, shared responsibility, pricing models, security services. Practice exam."}] },
  { id:"c82", title:"Solutions Architect Basics", titleBn:"AWS সলিউশনস আর্কিটেক্ট", part:"Certification + Advanced", sections:[{"id":"s1","type":"lesson","title":"Exam Overview","content":"SAA-C03: 130 min, 65 questions. Score 720/1000. Domains: Resilient 30%, High-Performing 28%, Secure 24%, Cost-Optimized 18%."},{"id":"s2","type":"lesson","title":"Design Patterns","content":"Multi-AZ vs Multi-Region. Event-driven vs request-response. Synchronous vs async. Stateful vs stateless. Microservices vs monolithic."},{"id":"s3","type":"lesson","title":"Exam Scenarios","content":"Design HA (ALB, ASG, RDS Multi-AZ). Migrate (DMS, MGN). Decoupled (SQS, SNS, EventBridge). Cost optimization (RIs, Spot, Lifecycle)."},{"id":"s4","type":"quiz","question":"SAA-C03 questions?","options":["55","65","75","85"],"correct":1,"explanation":"65 questions in 130 minutes."},{"id":"s5","type":"exercise","title":"Architecture Practice","description":"Design HA e-commerce: ALB, ASG, RDS Multi-AZ, SQS, ElastiCache, CloudFront, S3 Lifecycle."}] },
  { id:"c83", title:"Security Specialty Basics", titleBn:"AWS সিকিউরিটি স্পেশালিটি", part:"Certification + Advanced", sections:[{"id":"s1","type":"lesson","title":"Exam Overview","content":"SCS-C02: 170 min, 65 questions. Score 750/1000. Domains: Incident Response 14%, Logging/Monitoring 18%, Infrastructure 22%, Identity 20%, Data 26%."},{"id":"s2","type":"lesson","title":"Key Security Services","content":"IAM (users, groups, roles, policies, boundaries). Organizations (SCPs). KMS (key rotation, envelope encryption). CloudTrail, GuardDuty, Security Hub."},{"id":"s3","type":"lesson","title":"Security Patterns","content":"Incident response with Lambda automation. Infrastructure security with SGs/NACLs. Identity federation with IAM Identity Center. Data protection with KMS and Secrets Manager."},{"id":"s4","type":"quiz","question":"Which domain has highest weight in SCS-C02?","options":["Incident Response","Logging","Infrastructure","Data Protection"],"correct":3,"explanation":"Data Protection is 26% of the exam."},{"id":"s5","type":"exercise","title":"Security Design","description":"Design security for multi-account: Organizations + SCPs, centralized CloudTrail, GuardDuty + Security Hub, KMS multi-Region keys."}] },
  { id:"c84", title:"Enterprise Cloud Patterns", titleBn:"এন্টারপ্রাইজ ক্লাউড প্যাটার্ন", part:"Certification + Advanced", sections:[{"id":"s1","type":"lesson","title":"Enterprise Concerns","content":"Governance with SCPs and Organizations. Cost management with Budgets and Cost Explorer. Compliance with Config and Artifact. Multi-account strategy."},{"id":"s2","type":"lesson","title":"Migration Patterns","content":"Lift-and-shift (MGN). Database migration (DMS). Application refactoring (App2Container). Hybrid connectivity (Direct Connect, VPN, Transit Gateway)."},{"id":"s3","type":"lesson","title":"Enterprise Security","content":"Centralized security (GuardDuty, Security Hub across accounts). IAM Identity Center for SSO. Federation with Active Directory. Compliance automation with Config."},{"id":"s4","type":"quiz","question":"Which service enables hybrid connectivity?","options":["VPN","Direct Connect","Both","Neither"],"correct":2,"explanation":"Both VPN and Direct Connect enable hybrid connectivity."},{"id":"s5","type":"exercise","title":"Enterprise Design","description":"Multi-account strategy, centralized security, cost governance, hybrid connectivity, migration plan."}] },
  { id:"c85", title:"Mastery Recap + Certificate Prep", titleBn:"AWS মাস্টারি রিক্যাপ", part:"Certification + Advanced", sections:[{"id":"s1","type":"lesson","title":"Track Summary","content":"85 chapters across 9 parts: Cloud Foundations, IAM/Security, Compute, Storage/Databases, Networking, DevOps, Monitoring, Projects, Certification."},{"id":"s2","type":"lesson","title":"Key Skills","content":"Design HA/scalable architectures. Implement security best practices. Automate deployments. Optimize costs. Serverless and containerized applications."},{"id":"s3","type":"lesson","title":"Next Steps","content":"Pursue AWS certifications (Cloud Practitioner → Solutions Architect → Developer → Security Specialty). Build portfolio projects. Contribute to open source. Join AWS community."},{"id":"s4","type":"quiz","question":"First recommended AWS certification?","options":["Cloud Practitioner","Solutions Architect","Developer","Security"],"correct":0,"explanation":"Cloud Practitioner is the first recommended certification."},{"id":"s5","type":"exercise","title":"Final Project","description":"Design and document complete cloud architecture: multi-Region, HA, secure, cost-optimized, with CI/CD and monitoring."}] }]
};